(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c63"]=[{"id":"00015350","register_sub_id":"101","register_pk":"532474","name":"旧布江田家住宅（はる家ならまち）表門及び塀","kana":"きゅうふえだけじゅうたく（はるやならまち）おもてもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市南袋町31-4","lat":34.67645833,"lng":135.82638611,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"表門 木造、瓦葺、間口2.0m 塀 木造、瓦葺、総延長15m","structure_material":"表門 木造","registered":"2025.03.13(令和7.03.13)","register_no":"29 - 0366","desc":"敷地の西面に開く表門と左右に続く塀。表門は切妻造桟瓦葺の腕木門で、正面に石段を付し、門口に格子戸を建てる。塀は折れ曲り総延長１５メートル。屋根桟瓦葺で外壁漆喰塗仕上とし、腰は竪板張。蔵と連続して屋敷の表構えを整え、通りの歴史的な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015350"},{"id":"00015348","register_sub_id":"101","register_pk":"532472","name":"旧布江田家住宅（はる家ならまち）主屋","kana":"きゅうふえだけじゅうたく（はるやならまち）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市南袋町31-4","lat":34.67649167,"lng":135.82650556,"geo_status":"db","era":"昭和15年／平成29年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造2階建、瓦葺、建築面積174㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"29 - 0364","desc":"奈良町の南西部に位置する旧実業家の主屋。敷地中央に西面して建つ、つし二階建切妻造桟瓦葺で北に２列6室を並べ、北東を床構え付き座敷。南は落棟の土間で煙出を設ける。二階外壁は漆喰塗で虫籠窓を開け袖壁を付す。土間南西隅に洋室も備えた大規模な住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015348"},{"id":"00015349","register_sub_id":"101","register_pk":"532473","name":"旧布江田家住宅（はる家ならまち）蔵","kana":"きゅうふえだけじゅうたく（はるやならまち）くら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市南袋町31-4","lat":34.67653889,"lng":135.82639167,"geo_status":"db","era":"昭和15年頃／平成29年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"29 - 0365","desc":"敷地北西隅に位置する土蔵。通りに面して建つ、２階建切妻造平入本瓦葺で東面に戸口を開けて庇を付す。外壁は漆喰塗仕上で軒蛇腹を廻らし、腰は敷地内を海鼠壁仕上とする以外は竪板張。小屋組は妻梁で地棟を受け束立で棟木を支持。表構えをつくる重厚な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015349"},{"id":"00014907","register_sub_id":"101","register_pk":"519167","name":"旧増岡家住宅内蔵","kana":"きゅうますおかけじゅうたくうちくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県宇陀市大宇陀西山91","lat":34.48308611,"lng":135.93037778,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"29 - 0360","desc":"敷地中央に建つ家財蔵。土蔵造二階建切妻造平入、置屋根形式の桟瓦葺、東側に接続する離れとの廊下を蔵前とする。外壁は漆喰塗仕上で腰に焼杉板を張り、蔵前は中塗仕上とする。内部は各階板張。建築当初の雰囲気を残し、離れと一体で敷地中央の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014907"},{"id":"00014905","register_sub_id":"101","register_pk":"519165","name":"旧増岡家住宅主屋","kana":"きゅうますおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県宇陀市大宇陀西山91","lat":34.48305833,"lng":135.93056111,"geo_status":"db","era":"明治36年／平成29年改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造2階建、瓦葺、建築面積170㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"29 - 0358","desc":"宇陀松山旧城下町でかつて醤油醸造を営んだ商家の主屋。切妻造平入桟瓦葺で整形六間取、北端土間部は屋根を一段下げ煙出を設ける。正面は格子と黒漆喰の虫籠窓とし出桁で軒を深く出す。二階は船底天井の六室を配す。通りに面し、歴史的な景観を形成する町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014905"},{"id":"00014908","register_sub_id":"101","register_pk":"519168","name":"旧増岡家住宅外蔵","kana":"きゅうますおかけじゅうたくそとくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県宇陀市大宇陀西山91","lat":34.48315,"lng":135.93041667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"29 - 0361","desc":"敷地北端中央に南面して建つ二棟一体の土蔵。二階建切妻造平入桟瓦葺。米蔵東に一段棟の低い味噌蔵を接続。正面下屋は味噌蔵屋根から葺降ろし、下屋中央に井戸を設ける。小屋組は米蔵は和小屋、味噌蔵は登梁形式。敷地外郭をなす土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014908"},{"id":"00014906","register_sub_id":"101","register_pk":"519166","name":"旧増岡家住宅離れ","kana":"きゅうますおかけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県宇陀市大宇陀西山91","lat":34.48308889,"lng":135.93044722,"geo_status":"db","era":"昭和前期／平成29年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積39㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"29 - 0359","desc":"主屋背後に建つ離れ。一部二階建切妻造桟瓦葺。一階南面は全面ガラス戸の廊下とし、北に六畳間、風呂場、脱衣、便所を配す。二階は竿縁天井、長押、床を備える六畳間とする。内外に結霜ガラスを用い、ガラス戸が並ぶ開放的な外観が敷地中央の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014906"},{"id":"00016581","register_sub_id":"101","register_pk":"574943","name":"旧和田家住宅（松井家住宅）店舗兼主屋","kana":"きゅうわだけじゅうたく（まついけじゅうたく）てんぽけんおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市脇戸町11","lat":34.67797972,"lng":135.82948778,"geo_status":"db","era":"大正前期／昭和24年頃・令和4年改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積54㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0375","desc":"奈良町に位置する旧呉服商の店舗兼主屋。通りに西面する二階建切妻造平入桟瓦葺、外壁は黒漆喰塗で軒を現し、窓周囲に額縁を廻らし、両端部に袖壁を付す。１階はかつて通り土間沿いに３室を配し、2階東に端正な座敷を残す。建ちが高く時代相を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016581"},{"id":"00012594","register_sub_id":"101","register_pk":"367888","name":"教育大学前の町家","kana":"きょういくだいがくまえのまちや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市紀寺町862-5","lat":34.674694,"lng":135.838455,"geo_status":"geocoded","era":"昭和15年／平成27年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"29 － 0270","desc":"奈良町東南部に建てられた貸家群の一つで北面して建つ。東西棟の切妻造、南北二面に下屋を付し、路地に東妻をみせる。東に玄関、玄関の間、茶の間、台所、西に座敷、奥の間の各室を並べる。座敷に釣床や平書院を設けるなど昭和前期の貸家住宅の一形式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012594"},{"id":"00006928","register_sub_id":"101","register_pk":"107910","name":"粉川家住宅石垣","kana":"こかわけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1211","lat":34.67844409,"lng":135.84085409,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、延長52m","structure_material":"石造","registered":"2008.03.07(平成20.03.07)","register_no":"29 － 0130","desc":"敷地の南辺に築造され、表門の前庭東西にまわり込む。東方が折曲り長２０ｍ、西方が長３２ｍで、花崗岩の切石を前面道路の傾斜に合わせて高さ２～３ｍ、６～８段に積み、上面に板状笠石を載せる。内側には土を盛り上げ、敷地の造成と一体的に築造される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006928"},{"id":"00006926","register_sub_id":"101","register_pk":"107908","name":"粉川家住宅表門","kana":"こかわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1211","lat":34.67836411,"lng":135.8411194,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、瓦葺、間口2.4m、左右袖塀付","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"29 － 0128","desc":"敷地南辺から北へ６ｍ程度退いて東西棟で建つ。門口幅２．４ｍ、切妻造本瓦葺、総欅造の薬医門で、妻は撥束上に大斗肘木、軒は一軒疎垂木とする。東側離れ北西端との間に長１．６ｍ、西側に長２．２ｍの石積基礎、本瓦葺の袖塀が付き、東袖塀に潜りを設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006926"},{"id":"00006923","register_sub_id":"101","register_pk":"107905","name":"粉川家住宅主屋","kana":"こかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1211","lat":34.67856031,"lng":135.84112228,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"29 － 0125","desc":"奈良市街地東端辺りに所在。敷地中央東半に位置し、北に座敷棟、西に玄関棟、南に台所棟をコ字形に配する。座敷棟は入母屋造桟瓦葺のつし２階建で、軒先に銅板を葺いた下屋庇をまわし、西北の眺望を配慮し雁行形とする。内外とも上質な近代和風住宅の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006923"},{"id":"00006927","register_sub_id":"101","register_pk":"107909","name":"粉川家住宅築地塀","kana":"こかわけじゅうたくついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1211","lat":34.67841522,"lng":135.84133445,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土塀、瓦葺、延長29m","structure_material":"土塀","registered":"2008.03.07(平成20.03.07)","register_no":"29 － 0129","desc":"敷地南東隅から敷地東辺に沿って北へ長約３０ｍで築かれた築地塀で、東側隣地との南半を区切る。隣地との高低差のため擁壁を兼ねた玉石乱積基礎の上に建ち、壁は中塗仕上げとし、桟瓦葺の屋根を載せる。主屋などと一連の工事で築造された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006927"},{"id":"00006925","register_sub_id":"101","register_pk":"107907","name":"粉川家住宅土蔵","kana":"こかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1211","lat":34.678425,"lng":135.841232,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"29 － 0127","desc":"主屋台所棟の南方、離れの北方に南北棟で建つ。桁行６．０ｍ梁間４．０ｍ、切妻造本瓦葺の２階建で、西面から南面に下屋庇をまわし、南面は便所、西面は蔵前とする。西面中央に戸口、１階北面と２階南・北面に窓を開け、凝った意匠の窓庇を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006925"},{"id":"00006924","register_sub_id":"101","register_pk":"107906","name":"粉川家住宅離れ","kana":"こかわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1211","lat":34.678337,"lng":135.841217,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"29 － 0126","desc":"敷地南辺に位置する表門の東方に東西棟で建つ門長屋。桁行６間半梁間２間、寄棟造桟瓦葺の平屋建で、当初は西側３間半を使用人の住居、東側３間を納屋とした。真壁造で、腰は下見板張、上部は白漆喰塗とし、通りから望見できる西面には格子の出窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006924"},{"id":"00000455","register_sub_id":"101","register_pk":"101445","name":"古梅園主屋","kana":"こばいえんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68075823,"lng":135.82742206,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建，瓦葺，建築面積180㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0007","desc":"店舗の背後にあって，その間に接続する玄関棟とも表屋造形式になる。主体部は２階建で，全体に上質な和風建築となる。落ち棟の北妻側は路地に面し大壁造とする。中庭の北端を限る高塀とも一体的な漆喰塗の造作として，路地景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000455"},{"id":"00000458","register_sub_id":"101","register_pk":"101448","name":"古梅園中内蔵","kana":"こばいえんなかうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.6808084,"lng":135.82716701,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建，瓦葺，建築面積26㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0010","desc":"離れ座敷の西側に建つ２階建の小規模な土蔵で，内向き用の蔵として建てられた。周囲の建物とは接続せず独立して建つ。 北面は路地に面し，軒蛇腹廻りを除いて一面の板貼りとするが，２階に設けた開口部は２段構えとし，外観意匠を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000458"},{"id":"00000456","register_sub_id":"101","register_pk":"101446","name":"古梅園離れ座敷","kana":"こばいえんはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68081435,"lng":135.82726666,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"木造2階建，瓦葺，建築面積76㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0008","desc":"主屋の背後に位置し、中庭を挟んで建つ２階建の建物で、土蔵風の外観になる。 内部は１，２階とも贅を尽くした上等な造りとなり，２階軒は吹寄せの化粧小舞とする。 北妻側は，主屋から続く一連の高塀の意匠を保つ構成になり，町並みを整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000456"},{"id":"00000457","register_sub_id":"101","register_pk":"101447","name":"古梅園東内蔵","kana":"こばいえんひがしうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市椿井町７","lat":34.68072304,"lng":135.82718814,"geo_status":"db","era":"大正初年","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初年","structure":"土蔵造2階建，瓦葺，建築面積44㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"29 － 0009","desc":"離れ座敷の西南にあり，正面大戸口から続く通路に面して建つ２階建の土蔵。 軒蛇腹付大壁造で，腰板貼とする標準的な造作になり，２階には妻側，平側，とも小さな開口部を開く。 東妻側に蔵前があり，内向きの調度品等を納める蔵として使用される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000457"},{"id":"00008157","register_sub_id":"101","register_pk":"132598","name":"坂本家住宅主屋","kana":"さかもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市勝南院町12-1他","lat":34.6793351,"lng":135.83059752,"geo_status":"db","era":"江戸末期／昭和中期・平成18年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"29 － 0186","desc":"東西敷地の西端で通りに面して建つ平入町家。桁行７．４ｍ梁間９．９ｍ、木造つし２階建、切妻造桟瓦葺である。正面北側に出格子をたて、入口は格子戸引違い、南端に出格子窓を設け、外壁は漆喰塗で腰を竪板張とする。奈良町の伝統的な町家形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008157"},{"id":"00015351","register_sub_id":"101","register_pk":"532475","name":"さくら茶屋（山本家住宅長屋）","kana":"さくらちゃや（やまもとけじゅうたくながや）","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県御所市1603-18他","lat":34.46087778,"lng":135.73596111,"geo_status":"db","era":"明治後期／昭和前期・令和4年・同6年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"29 - 0367","desc":"西御所の南西隅の環濠跡に位置し３戸からなる長屋。通りに南面して建つ、つし二階建切妻造平入桟瓦葺で正面に下屋を付す。間口は各戸で異なり、間取りは１列３室の中棟以外は１列２室とする。建ち低く、桁行11間の長大な長屋が地域の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015351"},{"id":"00012229","register_sub_id":"101","register_pk":"353029","name":"佐埜家住宅旧能舞台","kana":"さのけじゅうたくきゅうのうぶたい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県奈良市中新屋町9","lat":34.677394,"lng":135.83021,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"29-268","desc":"敷地の背面側に建つ。梁間四・九メートル、桁行七・六メートル、平屋建、正面入母屋造、背面切妻造、桟瓦葺。現在は倉庫となるが、かつては能舞台で、東側三間が本舞台で、西側一間が後座であったと考えられる。町家に附属する能舞台として希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012229"},{"id":"00012227","register_sub_id":"101","register_pk":"353027","name":"佐埜家住宅主屋","kana":"さのけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市中新屋町9","lat":34.677409,"lng":135.830381,"geo_status":"db","era":"嘉永3年(1850)／昭和中期・同後期改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造2階建、瓦葺、建築面積88㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"29-266","desc":"奈良町の中心部に位置し、東面する。間口六・二メートル、奥行四六メートルの敷地の街路側に建ち、桁行三間、梁間八間の二階建で、切妻造平入。表屋造の構成を取る。南半を土間とし、北半一列に居室を並べる。奈良町の歴史的景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012227"},{"id":"00012228","register_sub_id":"101","register_pk":"353028","name":"佐埜家住宅渡廊下","kana":"さのけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市中新屋町9","lat":34.677409,"lng":135.830293,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"29-267","desc":"主屋背面中央部に取り付く。桁行三間梁間一間、切妻造桟瓦葺で、中庭に面する北側を手摺付の濡縁とし、南側には脱衣所、浴室、便所を配する。縁側には柱を立てず、丸材の軒桁を腕木で支え、軒の天井も鏡板張とするなど意匠を凝らした渡廊下である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012228"},{"id":"00013316","register_sub_id":"101","register_pk":"366305","name":"荘司家住宅内蔵","kana":"しょうじけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県生駒郡安堵町大字西安堵790","lat":34.6051008,"lng":135.75355278,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積30㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0298","desc":"主屋北側に接続して建つ道具蔵兼文書蔵。方二間の平面を成す置屋根形式の土蔵造本瓦葺で、西、南、東の三方に下屋を廻し、西面南側に戸口を開く。外壁は漆喰塗で軒裏も塗込め、軒下に鉢巻二段を廻して腰を竪板張とする。敷地北辺の屋敷構の一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013316"},{"id":"00013313","register_sub_id":"101","register_pk":"366302","name":"荘司家住宅主屋","kana":"しょうじけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県生駒郡安堵町大字西安堵790","lat":34.60506389,"lng":135.75349167,"geo_status":"db","era":"江戸後期／昭和39年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（金属板仮葺）一部瓦葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0295","desc":"代々村役を務めた旧家の主屋。敷地中央西寄に南面して建つ。屋根は大和棟で、両妻に落棟、正背面に下屋を付し、正面中央に式台玄関を設ける。内部は西に土間、東に前後2列4室と表側上手に突出した床付の座敷を配す。当地に残る希少な近世大和棟民家の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013313"},{"id":"00013318","register_sub_id":"101","register_pk":"366307","name":"荘司家住宅米蔵","kana":"しょうじけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡安堵町大字西安堵810-1","lat":34.60508889,"lng":135.75381389,"geo_status":"db","era":"大正2年頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0300","desc":"屋敷地東方、旧集落環濠で隔てた敷地北寄に南面して建つ。切妻造桟瓦葺で、南面に下屋を付す。外壁は漆喰を軒先まで塗込めて鉢巻を廻し、西、北、東面は腰に竪板を張る。内部は東西二室を分かれ、小屋を和小屋組とする。旧家の屋敷構拡張の様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013318"},{"id":"00013315","register_sub_id":"101","register_pk":"366304","name":"荘司家住宅新座敷及び稲納屋","kana":"しょうじけじゅうたくしんざしきおよびいなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県生駒郡安堵町大字西安堵790","lat":34.60504444,"lng":135.7537,"geo_status":"db","era":"明治中期／大正2年頃・昭和10年頃増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建一部2階建、瓦葺、建築面積73㎡、潜戸付塀付","structure_material":"木造平屋建一部2階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0297","desc":"敷地東辺南側に建つ。北側切妻造の新座敷と南側入母屋造の稲納屋から成り、東面中程に米蔵敷地へ至る切妻造の渡屋根、西面中程に別座敷に至る塀を付す。新座敷は上質な床構えを備え、稲納屋は長屋門風に東西に戸口を開く。旧環濠沿いの集落景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013315"},{"id":"00013317","register_sub_id":"101","register_pk":"366306","name":"荘司家住宅土蔵","kana":"しょうじけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県生駒郡安堵町大字西安堵790","lat":34.60511389,"lng":135.75366111,"geo_status":"db","era":"明治中期／昭和10年頃増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0299","desc":"敷地北東に建つ道具蔵。東面入母屋造、西面切妻造の桟瓦葺で、南面で別座敷、新座敷の廊下に接続する。外壁は漆喰塗で、腰は西面を海鼠壁、他を竪板張りとする。内部は板敷で壁を漆喰塗とし、小屋は和小屋組とする。内蔵と共に敷地北辺の屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013317"},{"id":"00013314","register_sub_id":"101","register_pk":"366303","name":"荘司家住宅別座敷","kana":"しょうじけじゅうたくべつざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒郡安堵町大字西安堵790","lat":34.60505278,"lng":135.75361111,"geo_status":"db","era":"明治32年／大正後期増築","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0296","desc":"主屋東側に接続して建つ。木造二階建、入母屋造桟瓦葺で、南北両面に主屋と一連の下屋を付し、南面東端に切妻屋根の角屋を突出する。内部は上下階とも東面に床を備えた座敷を配す。外壁は東面を杉皮張、他を漆喰塗とする。主屋と共に、敷地内景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013314"},{"id":"00016708","register_sub_id":"101","register_pk":"579192","name":"杉澤家住宅井戸屋形","kana":"すぎさわけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718097,"lng":135.769234,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、面積12㎡、井戸付","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0392","desc":"セイロ蔵の北西に位置する井戸屋形。平屋建切妻造桟瓦葺の南北棟で、北面と東西下方を開放とし、南面西寄りに引戸を開けて中庭への通用口とする。内部は土間とし、北東に石組の井戸を配し、上部は梁に束立の小屋組を現す。旧家の生活の様相を伝える井戸屋形。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016708"},{"id":"00016706","register_sub_id":"101","register_pk":"579190","name":"杉澤家住宅内蔵","kana":"すぎさわけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718061,"lng":135.769327,"geo_status":"db","era":"江戸末期／明治33年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0390","desc":"主屋の北側に位置する家財蔵。土蔵造二階建切妻造平入で置屋根形式の本瓦葺。外壁漆喰塗で軒に鉢巻を廻らし、腰は竪板を高く張る。南面東寄りの戸口に土戸を開き、内部は各階板敷で、小屋は曲梁に束を立て母屋と棟木を受ける。歴史的な屋敷構えをつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016706"},{"id":"00016704","register_sub_id":"101","register_pk":"579188","name":"杉澤家住宅主屋","kana":"すぎさわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.71796,"lng":135.769417,"geo_status":"db","era":"江戸後期／明治中期・昭和40年代改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺及び瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0388","desc":"押熊八幡神社の東方に位置する旧家の主屋。敷地中央に南面して建つ、切妻造平入茅葺で両端を落棟とし、三方に下屋を廻す。東は土間、西は７室を配し、南西の仏間は棹縁天井で、他は根太天井とする。大和棟の民家で整然とした外観が庄屋屋敷の姿をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016704"},{"id":"00016711","register_sub_id":"101","register_pk":"579195","name":"杉澤家住宅北門屋","kana":"すぎさわけじゅうたくきたもんや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718193,"lng":135.769415,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0395","desc":"敷地北面の東寄りに位置する長屋門。材木小屋の東に続く、平屋建入母屋造東西棟桟瓦葺。外壁北面は鼠漆喰塗で腰竪板張とする。西寄りに門口を設け、東に板敷の物置と倉庫、西に土間の納屋を配し、上部に和小屋を現す。石垣上に建ち、長大な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016711"},{"id":"00016713","register_sub_id":"101","register_pk":"579197","name":"杉澤家住宅米蔵及び納屋","kana":"すぎさわけじゅうたくこめぐらおよびなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.717908,"lng":135.769592,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造及び木造平屋建、瓦葺、建築面積120㎡","structure_material":"土蔵造及び木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0397","desc":"主屋東側に建つ米蔵及び納屋。米蔵は土蔵造平屋建切妻造平入で置屋根形式の桟瓦葺とする。北に落棟で平屋建切妻造の納屋を延ばし、西面に一連で下屋を付す。米蔵は一室の板敷で上部は和小屋で野地板を土塗とした特徴的なつくり。敷地東側の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016713"},{"id":"00016710","register_sub_id":"101","register_pk":"579194","name":"杉澤家住宅材木小屋","kana":"すぎさわけじゅうたくざいもくごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718157,"lng":135.7693,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0394","desc":"敷地北面の西寄りに位置する木小屋。平屋建切妻造桟瓦葺の東西棟で南面に下屋を付す。外壁は南面は漆喰塗、北面は鼠漆喰塗で腰は竪板張とする。内部は１室の広い土間で上部を高く吹抜け、曲梁に束立を用いた小屋を現す。北西土蔵に続き、屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016710"},{"id":"00016705","register_sub_id":"101","register_pk":"579189","name":"杉澤家住宅新座敷","kana":"すぎさわけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718013,"lng":135.769351,"geo_status":"db","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0389","desc":"主屋と内蔵の間に位置する座敷棟。南北棟で南西は入母屋造、南東は切妻造、北は両下造で桟瓦葺とし、東面に下屋を付す。内部は６畳２室を配し、縁を設ける。北室は内蔵の蔵前に用い、南室は西面に床と付書院を並べ、黒柿の床柱など、瀟洒なつくりの座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016705"},{"id":"00016707","register_sub_id":"101","register_pk":"579191","name":"杉澤家住宅セイロ蔵","kana":"すぎさわけじゅうたくせいろぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718054,"lng":135.769266,"geo_status":"db","era":"明治33年","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0391","desc":"内蔵の西に建つ家財蔵。土蔵造２階建切妻造平入、本瓦葺の置屋根形式で、南面に下屋を付す。外壁漆喰塗で腰は南は海鼠壁、北・西は高い竪板張。内壁は厚板を積上げる、いわゆる井籠蔵。小屋は曲梁に束を立て野地板を流板に張る。丁寧で特徴的なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016707"},{"id":"00016709","register_sub_id":"101","register_pk":"579193","name":"杉澤家住宅北西土蔵","kana":"すぎさわけじゅうたくほくせいどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718142,"lng":135.769234,"geo_status":"db","era":"明治前期／昭和前期頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0393","desc":"敷地北西隅に位置する家財蔵。南面して建つ土蔵造２階建切妻造平入桟瓦葺で、南面東寄りに庇を付し、大きく湾曲する持送で支える。外壁は大壁漆喰塗で軒を塗込めず木部を現す。各階一室の板敷で小屋は曲梁に束立の和小屋。角地に建ち屋敷景観の要となる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016709"},{"id":"00016712","register_sub_id":"101","register_pk":"579196","name":"杉澤家住宅味噌部屋及び柴小屋","kana":"すぎさわけじゅうたくみそべやおよびしばごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市押熊町340","lat":34.718016,"lng":135.769567,"geo_status":"db","era":"明治中期／明治後期増築、平成26年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0396","desc":"主屋の北東に位置する付属屋。平屋建入母屋造桟瓦葺の南北棟で、南は米蔵及び納屋に接続する。南半は味噌部屋、北半は柴小屋に用い、西面にそれぞれ戸口を開け、内部はいずれも土間とし小屋は梁に束立とする。小規模ながら主屋東側の屋敷構えの一画を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016712"},{"id":"00003690","register_sub_id":"101","register_pk":"104680","name":"ぜいたく豆本舗本店旧応接室","kana":"ぜいたくまめほんぽほんてんきゅうおうせつしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"奈良県","address":"奈良県奈良市角振町24-1","lat":34.682171,"lng":135.82737011,"geo_status":"db","era":"昭和26頃","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"29 － 0073","desc":"西蔵の前面側に接して建つ。屋根は入母屋造で，軒下には銅板葺の小庇を巡らす。内部は板敷の一室とし，南東の中庭側に大きな採光面を取る。天井を折上げ格天井とするなど意匠的にも優れ，開口部建具などが改造されているが，全体として旧状を良く留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003690"},{"id":"00003689","register_sub_id":"101","register_pk":"104679","name":"ぜいたく豆本舗本店西蔵","kana":"ぜいたくまめほんぽほんてんにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市角振町24-1","lat":34.682213,"lng":135.827377,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"29 － 0072","desc":"敷地奥の西側に建ち，東蔵とは軒を接する。南北棟，切妻造，妻入の２階建土蔵で，外壁は東面を腰海鼠壁，西面を腰板張，背面を板張とする。屋根野地面は東蔵と同様で，ほぼ同規模であるが２階部南面に窓を開くなどの違いがある。前面に旧応接室が取り付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003689"},{"id":"00003688","register_sub_id":"101","register_pk":"104678","name":"ぜいたく豆本舗本店東蔵","kana":"ぜいたくまめほんぽほんてんひがしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市角振町24-1","lat":34.68221395,"lng":135.82744902,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2003.12.01(平成15.12.01)","register_no":"29 － 0071","desc":"敷地奥の東側に建つ。妻入の土蔵造２階建で，外壁は白漆喰塗込を主とするが，背面側は全面板張である。屋根は垂木なしで，桁，母屋，棟木に直接一枚板をかけて野地とし，瓦を葺く。主屋後方の中庭を構成する要素で、奈良町の町家付属建物の様子を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003688"},{"id":"00002164","register_sub_id":"101","register_pk":"103154","name":"辰巳家住宅一の蔵","kana":"たつみけじゅうたくいちのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.612179,"lng":135.73120821,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積64㎡、南面庇附属","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0049","desc":"宅地の東面南端部に棟を南北に通して建つ。２階建，切妻造，桟瓦葺の土蔵造で，西正面には南に隣接する二の米蔵及び北の納屋と一連の庇が付く。南の２棟の米蔵よりやや規模が小さいがほぼ同形式になる重厚な造りで，保存状態もよい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002164"},{"id":"00002169","register_sub_id":"101","register_pk":"103159","name":"辰巳家住宅一の米蔵","kana":"たつみけじゅうたくいちのこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.611824,"lng":135.731583,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積40㎡、西面庇附属","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0054","desc":"宅地北面の西端部に建つ。２階建，切妻造，本瓦葺の土蔵造で，外壁は漆喰で仕上げ，屋敷側は腰を海鼠壁，外面する北面は高く竪板張りとする。丁寧な仕事による上質な造りで，長屋門と並んで屋敷の正面構えを構成する重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002169"},{"id":"00002166","register_sub_id":"101","register_pk":"103156","name":"辰巳家住宅三の蔵","kana":"たつみけじゅうたくさんのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61183428,"lng":135.73141169,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0051","desc":"二の米蔵の西に並んで建つ。２階建，切妻造，本瓦葺，土蔵造で，３棟のうち最も規模が大きい。立ちは高くないが，切石積基礎など上質なつくりで，大振りな軒蛇腹や出の深い北正面の庇など重厚な外観をもち，保存状態も良好である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002166"},{"id":"00002171","register_sub_id":"101","register_pk":"103161","name":"辰巳家住宅三の米蔵","kana":"たつみけじゅうたくさんのこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.6117431,"lng":135.73145387,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積60㎡、北面庇附属","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0056","desc":"主屋の南方，茶室の東に接して建つ。２階建，切妻造，土蔵造で，外部漆喰仕上げ，腰部分を竪板張りとする。他の土蔵に比べ規模が小さく，渡り廊下で主屋と連絡し，茶室・納戸が接続するなど内蔵的な性格をもつ。屋根はこの土蔵のみ置き屋根形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002171"},{"id":"00002160","register_sub_id":"101","register_pk":"103150","name":"辰巳家住宅主屋","kana":"たつみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61201183,"lng":135.7313801,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積410㎡","structure_material":"木造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0045","desc":"旧法隆寺村西里の大地主の屋敷。主屋は，２階建，入母屋造，桟瓦葺，間口約３０メートルに及ぶ大型の建物で，１，２階とも床棚を備えた座敷を配する。外観は，当地方の民家の形式を踏襲する一方で，内部は良材をふんだんに使った格調高い書院の意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002160"},{"id":"00002167","register_sub_id":"101","register_pk":"103157","name":"辰巳家住宅炭小屋","kana":"たつみけじゅうたくすみごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.6120411,"lng":135.7315711,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0052","desc":"主屋東に隣接して建つ。平屋建，切妻造，桟瓦葺の簡素なつくりだが，外壁は大壁，漆喰仕上げとする。炭を貯蔵するための施設で，屋敷構えを構成する上で欠かせない建物であり，南方の米蔵，納屋などとともに屋敷東面の景観を整える要素ともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002167"},{"id":"00002162","register_sub_id":"101","register_pk":"103152","name":"辰巳家住宅茶室","kana":"たつみけじゅうたくちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.611828,"lng":135.73134614,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0047","desc":"主屋の南方，三の蔵に接続して建ち，主屋と渡り廊下で連絡する。４畳半床付きの茶室，その東の３畳の水屋，これらの北の縁よりなる。茶室ではあるが，入母屋造，桟瓦葺で，西妻の破風を漆喰で塗り込め，装飾付きの掛瓦を用いるなど，重厚な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002162"},{"id":"00002172","register_sub_id":"101","register_pk":"103162","name":"辰巳家住宅土塀","kana":"たつみけじゅうたくどべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61168819,"lng":135.73148789,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土塀、瓦葺、延長236m","structure_material":"土塀","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0057","desc":"宅地四周を区切る土塀で，北正面側は一段高く築く。全体に中塗り仕上げで，軒を蛇腹状に塗り込め桟瓦葺の屋根をのせる。基礎の石垣は一分の隙もない亀甲積みで，高く築かれた南面では優美な曲面をつくる。壮大な屋敷構えを構成する主要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002172"},{"id":"00002161","register_sub_id":"101","register_pk":"103151","name":"辰巳家住宅長屋門","kana":"たつみけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61221148,"lng":135.73140304,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡、西方土塀附属","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0046","desc":"宅地北正面，中央やや東に建つ。一重，入母屋造，桟瓦葺の長屋門で，中央門口は両開き扉の出入口の両脇に潜りを開ける。門口両脇に各一部屋ずつを配し，西の部屋の表側には出格子窓を設ける。吟味された良材，黒漆喰塗りの外壁など，丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002161"},{"id":"00002168","register_sub_id":"101","register_pk":"103158","name":"辰巳家住宅納屋","kana":"たつみけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61189534,"lng":135.73158366,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積24㎡、西面庇附属","structure_material":"土蔵造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0053","desc":"主屋南東の土塀際に，米蔵の北に並んで建つ。２階建，切妻造，桟瓦葺，土蔵造の建物で，西正面には南の土蔵から連続する庇が取付く。作業用の施設だが上質なつくりで，棟高はやや低いが南の米蔵と外観を合わせ，屋敷東面の景観を整える要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002168"},{"id":"00002165","register_sub_id":"101","register_pk":"103155","name":"辰巳家住宅二の蔵","kana":"たつみけじゅうたくにのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61209742,"lng":135.731171,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積69㎡、東面庇附属","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0050","desc":"宅地北西部，一の蔵の南に棟を直交して建つ。２階建，切妻造，桟瓦葺の土蔵造で，一の蔵とほぼ規模，形式を同じくする。東面に桟瓦葺の庇を設け，主屋から一の蔵に至る吹放しの渡り廊下とする。妻面窓部分に鏝絵による宝尽し文を付すなど，意匠に凝る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002165"},{"id":"00002170","register_sub_id":"101","register_pk":"103160","name":"辰巳家住宅二の米蔵","kana":"たつみけじゅうたくにのこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61174628,"lng":135.73157652,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積48㎡、北面庇附属","structure_material":"土蔵造2階建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0055","desc":"宅地南東隅に棟を東西に通して建つ。２階建，切妻造，本瓦葺の土蔵造で，外壁は漆喰仕上げとし，庇が取り付く北正面を除く三方は高く腰板張りとする。東面では，高く築いた土塀越しに大きな軒蛇腹をもつ妻を見せ，屋敷構えの重要な要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002170"},{"id":"00016715","register_sub_id":"101","register_pk":"579199","name":"辰巳家住宅平地門及び塀","kana":"たつみけじゅうたくへいじもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西一丁目1828-2他","lat":34.612134,"lng":135.731382,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"平地門 木造、瓦葺、間口1.7m 塀 木造、瓦葺、総延長11m","structure_material":"平地門 木造","registered":"2026.07.09(令和8.07.09)","register_no":"29 - 0399","desc":"旧法隆寺村西里の大地主の屋敷内で、北庭を区画する庭門及び塀。平地門は切妻造本瓦葺の薬医門で、腕木の木鼻や斗は雲肘木・雲斗風とする。両脇の塀は木造、本瓦葺、大壁は外を漆喰塗、内を櫛目仕上とする。当地域らしい復古的な意匠を用いた門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016715"},{"id":"00002163","register_sub_id":"101","register_pk":"103153","name":"辰巳家住宅渡り廊下","kana":"たつみけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺西1-1826-1他","lat":34.61190559,"lng":135.73139048,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"29 － 0048","desc":"三の蔵の北に接する南北に長い建物で，西半間通りを主屋から三の蔵・茶室に至る渡り廊下，その東を納戸とする。簡素な造りだが，木柄の細い柱，梁からなり，繊細な格子窓など瀟洒な意匠で，三の蔵や茶室とともに内向き部分を構成する要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002163"},{"id":"00010032","register_sub_id":"101","register_pk":"196179","name":"近田家住宅蔵","kana":"ちかだけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市鵲町19-1","lat":34.67740892,"lng":135.831654,"geo_status":"db","era":"昭和8頃／平成20改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積28㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"29 － 0208","desc":"敷地西奥の元興寺境内地境に建ち、北妻の梁間が短い台形平面である。切妻造桟瓦葺で、南半の棟を下げて段違いとする。外壁は漆喰塗で、腰は竪板張である。東面南寄りの戸口に、瓦葺の庇を付ける。内部は南半が土間で西に扉を開く。北半は床板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010032"},{"id":"00010031","register_sub_id":"101","register_pk":"196178","name":"近田家住宅主屋","kana":"ちかだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市鵲町19-1","lat":34.6773997,"lng":135.83188501,"geo_status":"db","era":"昭和8／平成20改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積87㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"29 － 0207","desc":"元興寺東側の街路に東面する町家。切妻造桟瓦葺で南側土間部を落棟とし、正面を下屋とする。一階は、表からミセノマなど三室を並べ、二階の一〇畳はトコ廻りや天井等に銘木を用いるなど上質な造作とする。二階居室の採光に配慮した昭和初期らしい立面を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010031"},{"id":"00005025","register_sub_id":"101","register_pk":"106015","name":"辻家住宅土蔵","kana":"つじけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県天理市丹波市町20","lat":34.59356783,"lng":135.834488,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"29 － 0092","desc":"主屋床上部の西方，敷地北辺沿いに南北棟で建つ。桁行２間，梁間２間規模，切妻造，本瓦葺の２階建土蔵で，東面に桟瓦葺の下屋庇を差し掛けて戸口を設ける。外部は漆喰塗とし，２階に片開き窓，軒に換気口を開ける。主屋背面中庭を囲う構成要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005025"},{"id":"00012782","register_sub_id":"101","register_pk":"367685","name":"藤間家住宅表門及び土塀","kana":"とうまけじゅうたくおもてもんおよびどべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市高畑町1325-1","lat":34.67608778,"lng":135.84471083,"geo_status":"db","era":"江戸後期／昭和35年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"表門 木造、瓦葺、間口1.7m 土塀 土塀、瓦葺、総延長48m","structure_material":"表門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"29 － 277","desc":"敷地北面の街路に開く門と左右に延びる塀からなる。門は切妻造本瓦葺の薬医門で、主に欅材を用い、正面側に鏡天井を張る。塀は基礎乱石積、屋根瓦葺の土塀で、主要部を本瓦で葺く。社家の伝統的な表構えを伝えるとともに社家町の景観の構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012782"},{"id":"00012781","register_sub_id":"101","register_pk":"367684","name":"藤間家住宅主屋","kana":"とうまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市高畑町1325-1","lat":34.67608778,"lng":135.84471083,"geo_status":"db","era":"江戸後期／江戸末期・明治期・昭和35年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積158㎡","structure_material":"木造平屋一部2階建","registered":"2019.03.29(平成31.03.29)","register_no":"29 － 276","desc":"春日大社南方の旧社家町にあり、主屋は前庭の奥に北面して建つ。切妻造桟瓦葺の平屋建一部二階建で、正背面に下屋を付す。東が旧土間で、西に2列に室を配し、東列前面に式台を設け、西列には座敷を並べる。江戸後期に遡る社家住宅の貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012781"},{"id":"00011388","register_sub_id":"101","register_pk":"209225","name":"冨田家住宅井戸屋形","kana":"とみたけじゅうたくいどやかた","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752536,"lng":135.724515,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、面積4.2㎡","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"29－0248","desc":"通りから長屋門に致る坂道の東側に西面して建つ。一間四方の規模で、切妻造桟瓦の屋根をかけ、東・北の二面は中塗仕上げとする。西と南の二面を開放し、西面には曲材の梁を架ける。高台に位置する敷地の中で重要な役割を果たす建物で、敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011388"},{"id":"00011383","register_sub_id":"101","register_pk":"209220","name":"冨田家住宅奥座敷","kana":"とみたけじゅうたくおくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752851,"lng":135.724419,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0243","desc":"南北棟の南面を入母屋造、北面を切妻造とする平屋建。内部は南面に床・棚を構える主座敷と八畳間からなり、東西に縁を、南寝間に接する北側には廊下を廻らす。敷地西南隅の石垣上に建ち、城郭を思わせる特徴ある景観の核となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011383"},{"id":"00011385","register_sub_id":"101","register_pk":"209222","name":"冨田家住宅北道具蔵及び北寝間","kana":"とみたけじゅうたくきたどうぐぐらおよびきたねま","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752989,"lng":135.724569,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"北道具蔵 土蔵造2階建、瓦葺 北寝間 木造平屋建、瓦葺 建築面積48㎡","structure_material":"北道具蔵 土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0245","desc":"南道具蔵及の北側に軒を連ねて建つ。切妻造本瓦葺、土蔵造二階建の北道具蔵と南側に付属する北寝間からなる。北寝間は六畳一室で、西面に張出縁を設けて石垣下を広く眺めることができ、東面は縁を介して主屋と接続する。道具蔵は二階建で、食器などを収める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011385"},{"id":"00011382","register_sub_id":"101","register_pk":"209219","name":"冨田家住宅米蔵及び焙炉納屋","kana":"とみたけじゅうたくこめぐらおよびほいろなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752725,"lng":135.724496,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"米蔵 土蔵造平屋建、瓦葺 焙炉納屋 木造平屋建、瓦葺 建築面積70㎡","structure_material":"米蔵 土蔵造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0242","desc":"長屋門の西側に切妻造の棟を連ねて建つ。東側の木造焙炉納屋と土蔵造の米蔵からなる。焙炉納屋は真壁の腰縦板張として長屋門と外観を揃え、内部は東三間を区切って男衆部屋を設ける。敷地正面の石垣、長屋門とともに敷地景観を構成する建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011382"},{"id":"00011380","register_sub_id":"101","register_pk":"209217","name":"冨田家住宅主屋","kana":"とみたけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752889,"lng":135.724656,"geo_status":"db","era":"明治23／昭和45頃・同50代後半・平成7改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造2階建、瓦葺、建築面積242㎡、門及び土塀付","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0240","desc":"山麓を石垣で造成した敷地中央に南面して建つ。切妻造つし二階建とし、四周に下屋を廻す。内部は右勝手の三列九間取で、南西隅の八畳座敷には縁を廻らす。中央列表側には式台付を設けるなど、格式を備え、明治期の上層農家の生活様式を今日に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011380"},{"id":"00011381","register_sub_id":"101","register_pk":"209218","name":"冨田家住宅長屋門","kana":"とみたけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752621,"lng":135.724624,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0241","desc":"敷地南面の石垣上に建つ。切妻造桟瓦葺、桁行一九メートル、漆喰仕上げの腰縦板張とし、西端に間口四・六メートルの両脇潜戸付の門口を開く。東側には男衆部屋、小屋、厠を配する。門は大断面の親柱と冠木を用いて豪壮に仕上げ、屋敷の重厚な表構を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011381"},{"id":"00011386","register_sub_id":"101","register_pk":"209223","name":"冨田家住宅離れ","kana":"とみたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752993,"lng":135.724676,"geo_status":"db","era":"明治後期／昭和45頃改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0246","desc":"敷地北面に建ち、西南隅を北道具蔵に接続する。切妻造桟瓦葺、木造平屋建で、小庭を挟んで主屋と対面する。外観は中塗仕上げ、内部は東から六畳間、風呂、便所を配する。主屋から連なる内向きの居室空間で、簡素な造りが明治期の日常生活の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011386"},{"id":"00011387","register_sub_id":"101","register_pk":"209224","name":"冨田家住宅味噌部屋","kana":"とみたけじゅうたくみそべや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752889,"lng":135.724834,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0247","desc":"敷地北面、主屋の東側に南面して建つ。切妻造桟瓦葺、木造平屋建。桁行二間、梁間一間半の規模で、外観は真壁の漆喰仕上げ、内部は土間で天井を張らない簡易な作りとする。主屋土間の背戸口脇に位置し、食品を貯蔵していたと伝える。敷地景観の一画をなす建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011387"},{"id":"00011384","register_sub_id":"101","register_pk":"209221","name":"冨田家住宅南道具蔵及び南寝間","kana":"とみたけじゅうたくみなみどうぐぐらおよびみなみねま","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県生駒市高山町3830","lat":34.752926,"lng":135.724494,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"南道具蔵 土蔵造2階建、瓦葺 南寝間 木造平屋建、瓦葺 建築面積46㎡","structure_material":"南道具蔵 土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0244","desc":"敷地西面の石垣上の中央に建つ。切妻造の二階建、土蔵造の南道具蔵と南側に付属する南寝間からなる。南寝間は外観も奥座敷と一連で仕上げる。傾斜地に築かれた石垣上に複数の棟が高さを違えながら軒を連ねる、変化に富む屋敷景観を形成する土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011384"},{"id":"00012230","register_sub_id":"101","register_pk":"353030","name":"豊﨑家住宅主屋","kana":"とよさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市西新屋町11","lat":34.676826,"lng":135.829961,"geo_status":"db","era":"江戸末期／明治前期・昭和初期・同57年・平成28年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積72㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"29 - 0269","desc":"桁行三間、梁間七間、切妻造平入で西面する。表側一間半を玄関土間とし、南側に吹抜けの土間を通し、北側に五畳間と６畳間を並べる。二階は表側一間半をつしとし、後方は板間と６畳座敷とする。古式を示す表構えで、地域の歴史的景観に寄与する町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012230"},{"id":"00014657","register_sub_id":"101","register_pk":"515199","name":"内藤家住宅主屋","kana":"ないとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市池田町122","lat":34.64161944,"lng":135.82071667,"geo_status":"db","era":"明治前期／明治後期・昭和40年頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積221㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"29 - 0353","desc":"奈良盆地のかつての環濠集落北端にある旧家の主屋。北向きの切妻造平入桟瓦葺で、東の土間側を入母屋造落棟とし、下屋を巡らす。間取りは土間を南北に区切り、西に二列六室を配す。床構え付の座敷は設けず離れに配して古式を示し、木太い良材を用いた造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014657"},{"id":"00014659","register_sub_id":"101","register_pk":"515201","name":"内藤家住宅中門","kana":"ないとうけじゅうたくちゅうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市池田町122","lat":34.64173333,"lng":135.82076667,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口1.4m 袖塀付","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"29 - 0355","desc":"旧家の主屋北側に東面する腕木門。切妻造本瓦葺、軒疎垂木小舞打、両脇に袖塀が付く。切石礎石に角柱を立て、門口は両開き襷桟板戸と横連子欄間として細部の造りも丁寧。長屋門から主屋に至る前庭と主屋北側の座敷庭を区画し、格式ある屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014659"},{"id":"00014660","register_sub_id":"101","register_pk":"515202","name":"内藤家住宅中庭北塀","kana":"ないとうけじゅうたくなかにわきたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市池田町122","lat":34.64175278,"lng":135.82071389,"geo_status":"db","era":"明治43年頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、延長12m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"29 - 0356","desc":"かつての環濠集落の旧家の屋敷北辺に建つ桟瓦葺の塀。延長十二・三メートル。北面は水路石積み護岸に延石を据え、大壁造漆喰仕上で腰板張とする。南面は真壁造漆喰仕上で、二箇所に花崗岩の控柱を設置し、座敷庭の背景となる。伝統的な農村景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014660"},{"id":"00014658","register_sub_id":"101","register_pk":"515200","name":"内藤家住宅長屋門及び塀","kana":"ないとうけじゅうたくながやもんおよびへい","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市池田町122","lat":34.64167222,"lng":135.82095,"geo_status":"db","era":"明治前期／昭和40年代改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"長屋門 木造平屋建、瓦葺、建築面積38㎡ 塀 木造、瓦葺、延長3.7m","structure_material":"長屋門 木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"29 - 0354","desc":"かつての環濠集落の旧家の長屋門で、敷地北東角に東面する。切妻造平入桟瓦葺、中央二間を袖壁付門口とし、引分け板戸を立てる。南北の室は物入れ。門口のまぐさや桁を漆喰で塗込める特徴的な意匠。窓が少なく閉鎖的な門構えで、集落の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014658"},{"id":"00013429","register_sub_id":"101","register_pk":"368514","name":"永井家住宅主屋","kana":"ながいけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市南魚屋町41、柳町9-2","lat":34.67892222,"lng":135.8254,"geo_status":"db","era":"江戸末期／大正前期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積213㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"29 － 0302","desc":"奈良旧市街の西部に位置し、通りに西面して建つ。つし二階建、切妻造桟瓦葺平入で、外壁は鼠漆喰塗。主体部正面二階に虫籠窓、両端に袖壁を備え、南に通り土間、北に居室を配し、主体部北側に落棟の座敷が続く。伝統的な表構えを残し、町並みの様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013429"},{"id":"00006477","register_sub_id":"101","register_pk":"107460","name":"中井家住宅座敷棟","kana":"なかいけじゅうたくざしきとう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県御所市南中町1234","lat":34.46174214,"lng":135.73738028,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"29 － 0123","desc":"主屋の西面北端に接続する。木造平屋建の東西棟で、屋根は切妻造桟瓦葺である。規模は桁行５間、梁間２間で、南面に瓦葺下屋をつけて縁とする。内部は西側にトコと棚、付書院を備えた座敷１０畳と次の間８畳からなる。良質な数寄屋風座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006477"},{"id":"00006476","register_sub_id":"101","register_pk":"107459","name":"中井家住宅主屋","kana":"なかいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県御所市南中町1234","lat":34.46168986,"lng":135.73749038,"geo_status":"db","era":"寛政4","year":1792,"year_source":"db","year_min":1792,"year_max":1792,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"29 － 0122","desc":"南中町通りに東面して建つ、間口６間半、奥行５間の町家。切妻造本瓦葺で、南に落棟がつく。内部は南が元は通り土間、北に２列６室を配す。正面に下屋を設けて縁とし、粗い格子をつける。つし２階外壁を黒漆喰、軒を白漆喰で塗り分け、特色ある外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006476"},{"id":"00006478","register_sub_id":"101","register_pk":"107461","name":"中井家住宅土蔵","kana":"なかいけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県御所市南中町1234","lat":34.46157889,"lng":135.73748562,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"29 － 0124","desc":"主屋の南に建つ土蔵造２階建で、桁行４間半、梁間２間規模の東西棟。切妻造桟瓦葺とし、北面に瓦葺庇をつけて蔵前とする。外壁は白漆喰塗で、両妻の腰を竪板張、北面の腰は海鼠壁とする。１階は二分して西を米蔵とした。歴史的な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006478"},{"id":"00010332","register_sub_id":"101","register_pk":"199105","name":"中川家住宅蔵","kana":"なかがわけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市今辻子町30-1","lat":34.683728,"lng":135.822861,"geo_status":"db","era":"大正4年／平成13年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積84㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"29-0218","desc":"敷地西奥に南北棟で建つ。土蔵造二階建、桁行一二メートル梁間四・九メートル、切妻造本瓦葺で、東面に桟瓦葺の下屋を設ける。外壁漆喰塗で鉢巻を廻らし上下階に窓を穿つ。戸口廻りに鳥居枠を表し、南面の腰下と西面に竪板を張る。重厚な趣の大型土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010332"},{"id":"00010329","register_sub_id":"101","register_pk":"199102","name":"中川家住宅主屋","kana":"なかがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市今辻子町30-1","lat":34.683699,"lng":135.823295,"geo_status":"db","era":"大正4年／平成13年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積143㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"29-0215","desc":"小路に東面する、間口の広いつし二階建町家。南側の通り土間の屋根を落棟とし、北側のミセ前面は平格子と出格子をたて、霧除を付す。上部は出桁で軒を深め、虫籠窓を穿ち、両端に袖壁を設ける。座敷飾や透彫欄間に、大正期らしい洗練さを備える上質な町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010329"},{"id":"00010331","register_sub_id":"101","register_pk":"199104","name":"中川家住宅離れ","kana":"なかがわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市今辻子町30-1","lat":34.683728,"lng":135.822975,"geo_status":"db","era":"昭和前期／平成13年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"29-0217","desc":"主屋後方に中庭を挟んで建つ。東面入母屋造、西面切妻造で、軒に丸太垂木を配る。庭側の東面は腰を洗出し、上部壁を鼠漆喰塗としてガラス窓をたてる。北面は上部漆喰塗、下部は竪板張である。庭側の採光に配慮した開放的な離れで、風情ある庭景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010331"},{"id":"00010333","register_sub_id":"101","register_pk":"199106","name":"中川家住宅煉瓦塀","kana":"なかがわけじゅうたくれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市今辻子町30-1","lat":34.6836583,"lng":135.82300294,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"煉瓦造、延長20m","structure_material":"煉瓦造","registered":"2014.12.19(平成26.12.19)","register_no":"29-0219","desc":"南隣地で操業していた当家の織物工場と、住宅敷地を区画していた煉瓦塀。花崗岩谷積とした擁壁上に布石を伏せ、煉瓦を長手積に一五段積み、頂部は二段に迫出して笠石状とする。また北面に一間間隔に控壁を設ける。伝統的な町家の屋敷地に近代の趣を添える塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010333"},{"id":"00010330","register_sub_id":"101","register_pk":"199103","name":"中川家住宅渡廊下","kana":"なかがわけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市今辻子町30-1","lat":34.683679,"lng":135.823119,"geo_status":"db","era":"大正4年／平成13年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"29-0216","desc":"主屋背面から離れの間を矩折れに繋ぐ渡廊下で、切妻造桟瓦葺。中庭に面する北側を板敷の廊下として南側に浴室や便所などを配し、北面内法をガラス窓、上部を摺ガラス欄間とする。廊下を吹放しとする奈良町家の通例と異なる形式で、瀟洒な意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010330"},{"id":"00014073","register_sub_id":"101","register_pk":"508333","name":"中谷家住宅主屋","kana":"なかたにけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県奈良市西紀寺町32-1","lat":34.674175,"lng":135.83313611,"geo_status":"db","era":"明治35年頃／平成30年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"29 - 0325","desc":"旧奈良町に所在し、通り沿いの門から前庭を挟んで北面する住宅。平屋建切妻造平入桟瓦葺。内部は東に土間を通して上部を吹抜とし、西に二列六室の居室を配する。表側土間境六畳は舞良戸を入れて式台風の構えで、玄関の間とする。旧市街に残る良質な近代住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014073"},{"id":"00002079","register_sub_id":"101","register_pk":"103069","name":"中村家住宅（旧足立家住宅）主屋","kana":"なかむらけじゅうたく（きゅうあだちけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1247-1","lat":34.67797096,"lng":135.84321045,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺、建築面積199㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0037","desc":"志賀直哉旧宅の東隣に位置。洋画家足立源一郎の自邸として建造された。設計も氏の手になる。木造２階建，外壁はモルタル仕上げとし，屋根には赤い桟瓦を葺く。玄関にステンドグラスをあしらい，吹抜のアトリエやサンルームを設えるなど，内部の見所も多い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002079"},{"id":"00002080","register_sub_id":"101","register_pk":"103070","name":"中村家住宅（旧足立家住宅）塀","kana":"なかむらけじゅうたく（きゅうあだちけじゅうたく）へい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市高畑町1247-1","lat":34.67804095,"lng":135.84347865,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土塀、瓦葺、延長65m、木造門柱一対付","structure_material":"土塀","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0038","desc":"屋敷地の北及び東側を区切る全長約７０ｍの土塀で，北側中央に門を開く。腰は乱石積で，その上はモルタル仕上げとし，屋根には主屋と同じく赤桟瓦を葺く。春日大社の旧社家町にあって洋風の土塀はよく景観になじみ，高畑の文化的な雰囲気をいまに伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002080"},{"id":"00011543","register_sub_id":"101","register_pk":"210488","name":"奈良町にぎわいの家蔵","kana":"ならまちにぎわいのいえくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市西新屋町19-2","lat":34.67722194,"lng":135.82999806,"geo_status":"db","era":"江戸後期／大正前期・平成27年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"29-0252","desc":"離れ南側に隣接し、東面して建つ。土蔵造の二階建、切妻造本瓦葺で、正面に下屋を出し、渡廊下に接続する。主要材を蛤刃仕上とするなど古式を示す。奈良旧市街の町家のなかでも古い例であり、伝統的な構成を伝える貴重な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011543"},{"id":"00011540","register_sub_id":"101","register_pk":"210485","name":"奈良町にぎわいの家主屋","kana":"ならまちにぎわいのいえしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市中新屋町5-1","lat":34.67724,"lng":135.83023389,"geo_status":"db","era":"大正6年／昭和後期・平成27年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積203㎡、高塀付","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"29-0249","desc":"奈良旧市街の中心部、中新屋町の街路南端に東面して建つ。表屋造の二階建、切妻造瓦葺で、表屋の北側面を入母屋とする。背面に入母屋造の別棟を突出し、各階に座敷を構えて北面に眺望を取る独特の構成をもち、近代における表屋造の展開をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011540"},{"id":"00011541","register_sub_id":"101","register_pk":"210486","name":"奈良町にぎわいの家離れ","kana":"ならまちにぎわいのいえはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県奈良市中新屋町5-1他","lat":34.677295,"lng":135.82999889,"geo_status":"db","era":"大正2年／平成27年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"29-0250","desc":"主屋後方に中庭を挟んで東面して建つ。切妻造桟瓦葺の平屋建で、渡廊下を介して主屋に接続する。一〇畳の座敷を中心に前後に下屋で縁を出し、それぞれ庭に開く。正面の円窓や手摺付の縁、付書院の花頭窓など瀟洒な意匠が近代町家の離れの様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011541"},{"id":"00011542","register_sub_id":"101","register_pk":"210487","name":"奈良町にぎわいの家待合","kana":"ならまちにぎわいのいえまちあい","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県奈良市中新屋町5-1","lat":34.67727111,"lng":135.83038,"geo_status":"db","era":"大正6年頃／平成27年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積2.8㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"29-0251","desc":"主屋正面の北側に付属する高塀の背面に南面して建つ。桟瓦葺の平屋建で、開放とする正面西半以外は土壁として円窓や菱窓をあしらい、丸太や竹、杉皮などを瀟洒に用いる。潜門をもつ高塀、主屋の茶室とともに露地の空間を構成し、奈良の茶文化の一端を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011542"},{"id":"00003903","register_sub_id":"101","register_pk":"104893","name":"西田家住宅石垣","kana":"にしだけじゅうたくいしがき","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.64457988,"lng":135.77905213,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"石造、延長161m","structure_material":"石造","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0082","desc":"敷地北面の正門の東側から，外周の北・東・南側に総延長１６０ｍに亘って築かれた石垣。最も高い場所では高さ２ｍを超える。出隅部を切石布積，他を亀甲積や谷積とし，高い施工精度を誇るとともに，城下町大和郡山の戦前の景観を今日に伝える建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003903"},{"id":"00003899","register_sub_id":"101","register_pk":"104889","name":"西田家住宅内蔵","kana":"にしだけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.644501,"lng":135.778732,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0078","desc":"主屋西棟と主屋南棟を結ぶ南北棟の土蔵で，２階建，切妻造，本瓦葺の置屋根形式である。東側には下屋を設けて廊下とし，南・北・西側壁面は縦板張，東側の廊下に面する壁のみ海鼠壁とする。敷地景観の核となると共に，精緻な装飾を備える土蔵の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003899"},{"id":"00003901","register_sub_id":"101","register_pk":"104891","name":"西田家住宅祠社","kana":"にしだけじゅうたくししゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.64476529,"lng":135.77861954,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、銅板葺、建築面積0.89㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0080","desc":"表門右手に建つ一間社流造の社殿。屋根は銅板葺で，二軒繁垂木とする。小規模な社殿であるが，高欄，脇障子，浜床に至るまで精緻に作り，擬宝珠，頭貫木鼻なども省略しない。大規模住宅にしばしば見られる祠の中でも技巧に富み，屋敷景観を形づくる建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003901"},{"id":"00003895","register_sub_id":"101","register_pk":"104885","name":"西田家住宅主屋中央棟","kana":"にしだけじゅうたくしゅおくちゅうおうとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.644581,"lng":135.778824,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積178㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0074","desc":"木造２階建，八棟造桟瓦葺で，建ちが高いのが特徴。１階は中央廊下を挟んで書院座敷を連ね，２階は広間２室である。北面中央に張り出す玄関は檜皮葺唐破風屋根。竹の間をはじめとし各室に特徴がある内装や豪壮な外観など質の高い近代和風住宅の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003895"},{"id":"00003897","register_sub_id":"101","register_pk":"104887","name":"西田家住宅主屋西棟","kana":"にしだけじゅうたくしゅおくにしとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.6446,"lng":135.77873434,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0076","desc":"主屋中央棟の西側に接し，南側で内蔵と接続されている。木造平屋建，入母屋造で北側に内玄関を設けている。内玄関扉の両脇には特徴ある七角形の飾り窓を配し，正面側ファサードのアクセントとなっている。内部は２室構成で屋敷景観の要をなす建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003897"},{"id":"00003896","register_sub_id":"101","register_pk":"104886","name":"西田家住宅主屋南棟","kana":"にしだけじゅうたくしゅおくみなみとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.64443863,"lng":135.77876255,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0075","desc":"敷地南端に建つ東西棟で，西側で内蔵と接する。平面は東から座敷８畳，次の間６畳，洋室を備え，洋室の北側には廊下を介して便所と風呂を設けている。座敷は床・棚・書院を備える本格的なつくりで，洋室の天井は寄木張とする。大規模住宅の離れ座敷の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003896"},{"id":"00003900","register_sub_id":"101","register_pk":"104890","name":"西田家住宅土蔵","kana":"にしだけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.644657,"lng":135.778625,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0079","desc":"主屋西棟の西方に接続する。桁行３間梁間２間の規模の大きい土蔵で，２階建，切妻造，本瓦葺であるが，置屋根形式とはせず，南側に下屋を差し掛けて入口を設けている。腰部は南面のみ海鼠壁，他は縦板張である。屋敷景観の重要な要素となる土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003900"},{"id":"00003902","register_sub_id":"101","register_pk":"104892","name":"西田家住宅拝所","kana":"にしだけじゅうたくはいしょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.64474522,"lng":135.77861959,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、銅板葺、建築面積3.36㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0081","desc":"祠社の前面に建つ。建築面積は３．３６㎡で，四本柱を建て，上部は菱格子の欄間を配し，舟肘木を設けている。屋根は二軒疎垂木に銅板葺である。全体に簡素ではあるが，欄間や蟇股などに意匠を凝らす。住宅に附属する祠の拝所としては類例の少ない建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003902"},{"id":"00003898","register_sub_id":"101","register_pk":"104888","name":"西田家住宅離れ座敷","kana":"にしだけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県大和郡山市箕山町37-1、2、3","lat":34.64464788,"lng":135.77912624,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"29 － 0077","desc":"敷地の東側庭園部分に建つ。２間四方規模，平屋建，入母屋造，銅板葺の小規模な建物で，敷地の中で唯一江戸間を用いている。西側壁面には丸窓を設け，天井は棹縁を放射状に配するなど数寄屋風の瀟洒な意匠を持ち，書院風の主屋などと対照をなす建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003898"},{"id":"00002976","register_sub_id":"101","register_pk":"103966","name":"葉本家住宅主屋","kana":"はもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県大和郡山市西観音寺町6","lat":34.65350565,"lng":135.78870262,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"29 － 0066","desc":"大和郡山城下から奈良に至る街道沿いに東面して建つ。明治期には両替商などを営んだ商家で，切妻造，平入，つし２階建で，煙出付の桟瓦葺である。１階の繊細な出格子やばったり床机，２階の細長の虫籠窓など整った外観で，旧街道の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002976"},{"id":"00002979","register_sub_id":"101","register_pk":"103969","name":"平井医院表門","kana":"ひらいいいんおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県五條市今井町4-1-16","lat":34.355766,"lng":135.706223,"geo_status":"db","era":"安政2頃","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造、瓦葺、間口9.0m","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"29 － 0069","desc":"約１２００㎡の広大な屋敷の南辺中央にある。南面して建つ長屋門形式の門で，入母屋造，桟瓦葺，出桁を用いて深い軒をつくる。中央に門口を設け，左右は真壁造で横連子窓を設け，腰を簓子下見板張とする。屋敷正面の景観構成上，欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002979"},{"id":"00002977","register_sub_id":"101","register_pk":"103967","name":"平井医院主屋","kana":"ひらいいいんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県五條市今井町4-1-16","lat":34.3559353,"lng":135.70616645,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積230㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"29 － 0067","desc":"五條市内の国道２４号線沿いに屋敷を構え，主屋は敷地中央にほぼ南面して建ち，上棟幣束より安政２年の建立とわかる。東西棟で切妻造，平入の細長い建物で，棟に切妻造の煙出，東妻に落棟，前後に庇を設けるなど豪壮な外観で，地域景観の際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002977"},{"id":"00002978","register_sub_id":"101","register_pk":"103968","name":"平井医院土蔵","kana":"ひらいいいんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県五條市今井町4-1-16","lat":34.35607838,"lng":135.70608316,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"29 － 0068","desc":"上棟幣束より主屋と同じ安政２年建立とわかる。東西棟の切妻造，桟瓦葺，２階建で，南面に戸前庇を架ける。屋根は棟が段違いで，東側が米蔵，西側が綿蔵として用いられた。主屋の後方，屋敷の北辺沿いにあり，国道沿いに残る歴史的景観の要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002978"},{"id":"00005339","register_sub_id":"101","register_pk":"106327","name":"藤岡家住宅内蔵","kana":"ふじおかけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38297859,"lng":135.70294215,"geo_status":"db","era":"寛政9","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0098","desc":"主屋の南にある。土蔵造２階建，東西棟の切妻造，本瓦葺で，重厚な扉を構える北面に蔵前を設けて主屋と接続し，西面は化粧部屋を設けて片流れの桟瓦葺屋根を架ける。街路側の妻面は小庇付の窓を設け，上部両端に鯉の漆喰鏝絵を施すなど，丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005339"},{"id":"00013428","register_sub_id":"101","register_pk":"368513","name":"藤岡家住宅主屋","kana":"ふじおかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県奈良市高畑町743-1","lat":34.6771,"lng":135.84068056,"geo_status":"db","era":"昭和23年頃／平成28年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"29 － 0301","desc":"奈良旧市街の東部に位置し、道路からやや後退し南面して建つ。木造平屋建、切妻造桟瓦葺で、外壁は中塗仕上で腰に竪板を張り、正面に出格子を建てる。内部は東側をトオリニワ、西側に三室を並べ、オクノマに床を構える。古都の景観を構成する町家の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013428"},{"id":"00005344","register_sub_id":"101","register_pk":"106332","name":"藤岡家住宅米蔵","kana":"ふじおかけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38309681,"lng":135.70311001,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積78㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0103","desc":"街路を挟んだ東の敷地に主屋と面して建つ。土蔵造平屋建，南北棟の切妻造，西面に下屋庇を設け，桟瓦葺とする。外壁は漆喰で垂木まで塗り，両側面と背面は縦板で覆う。内部は棹縁天井の広い１室とする。当地域における上層農家の屋敷構成を示す施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005344"},{"id":"00005338","register_sub_id":"101","register_pk":"106326","name":"藤岡家住宅主屋","kana":"ふじおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38307218,"lng":135.70292052,"geo_status":"db","era":"天保3","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0097","desc":"東を正面とし，北も街路に面した角地に建つ。平屋建，南北棟の入母屋造，平入で，周囲に下屋を廻し，桟瓦葺とする。平面は北半が土間で，南半の居室部は基本的に３室２列の構成になる。建築年代が明確で，改造も少なく，当地域における町家建築の指標になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005338"},{"id":"00010987","register_sub_id":"101","register_pk":"208957","name":"藤岡家住宅主屋","kana":"ふじおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市紀寺町771-1","lat":34.674183,"lng":135.833713,"geo_status":"db","era":"昭和3／昭和30代・同40代・平成25改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積99㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"29 - 0226","desc":"通りに北面するつし二階建。正面は出格子ほか多種の格子をたて、腰を竪板張とする。内部は東側の二列分を土間として中央に大黒柱を立て、床上部は食違い四間取として西奥を座敷とする。屋根を当初から瓦葺とするなど旧奈良町周縁部の農家建築の近代化を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010987"},{"id":"00005342","register_sub_id":"101","register_pk":"106330","name":"藤岡家住宅新座敷","kana":"ふじおかけじゅうたくしんざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38294737,"lng":135.70278359,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0101","desc":"敷地南よりのほぼ中央にあり，北には離座敷が取り付く。平屋建，寄棟造，桟瓦葺で，南に屋根を一段下げて式台玄関を突出させる。内部は西が１５畳，東が１０畳で，ともに格式の高い床を構え，柱から天井板まで上質の材を用いており，近代和風の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005342"},{"id":"00005346","register_sub_id":"101","register_pk":"106334","name":"藤岡家住宅築地塀","kana":"ふじおかけじゅうたくついじべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.3828476,"lng":135.70274035,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長78m","structure_material":"土塀","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0105","desc":"敷地東辺の薬医門から南に下がり，南辺を経て，西面の新座敷まで至る折曲り総延長約７８ｍの築地塀。東面は浅葱色のモルタル塗，ほかは内面漆喰仕上げ，外面中塗り仕上げとし，南面ほぼ中央に潜戸を設ける。大規模屋敷に相応しい重厚な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005346"},{"id":"00005341","register_sub_id":"101","register_pk":"106329","name":"藤岡家住宅離座敷","kana":"ふじおかけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38303072,"lng":135.70276051,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0100","desc":"主屋西に渡廊下で繋がり，南には新座敷が取り付く。平屋建，片入母屋造，桟瓦葺で，東や北に角屋を突出する。内部は北より床・棚付の６畳，６畳，納戸の３室構成で，東と西の両側に縁を設ける。隠居と称する簡素な建物であるが，細部のつくりは丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005341"},{"id":"00005347","register_sub_id":"101","register_pk":"106335","name":"藤岡家住宅塀","kana":"ふじおかけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38318675,"lng":135.70264286,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長14m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0106","desc":"敷地の北西隅にある延長１３．６ｍのＬ字型の塀で，乱石積基礎の上に建つ。真壁造で，壁は漆喰塗とし，腰を縦板で覆う。腕木で軒桁を受け，板軒で桟瓦葺屋根とする。隅では西辺を一段高くして変化をもたせる。金剛山への参詣道の街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005347"},{"id":"00005340","register_sub_id":"101","register_pk":"106328","name":"藤岡家住宅別座敷","kana":"ふじおかけじゅうたくべつざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38312114,"lng":135.70266519,"geo_status":"db","era":"嘉永6","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積99㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0099","desc":"敷地の北西隅に建つ。平屋建，南北棟の入母屋造で，周囲に下屋を廻し，東に入母屋造の式台玄関を設け，西に茶室等を角屋で突出する。屋根は総桟瓦葺。内部は床・棚を構えた上質の８畳２室からなり，玄関奥には６畳を設ける。全体として格式の高い接客用施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005340"},{"id":"00005345","register_sub_id":"101","register_pk":"106333","name":"藤岡家住宅薬医門","kana":"ふじおかけじゅうたくやくいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38293414,"lng":135.70301037,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0104","desc":"敷地東辺の南，内蔵に接し，間口１．８ｍの１間薬医門で，屋根は本瓦葺，総欅造とする。控柱の頭貫を親柱の冠木に架けて正面へ肘木状に延ばし，斗，肘木で桁を受けるなど，凝った造作をみせる。大規模屋敷の風格ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005345"},{"id":"00005343","register_sub_id":"101","register_pk":"106331","name":"藤岡家住宅渡廊下","kana":"ふじおかけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県五條市近内町526","lat":34.38308152,"lng":135.70281438,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"29 － 0102","desc":"前方にある主屋と，後方の離座敷や別座敷を繋いでいる。２階建，西面入母屋造，東面切妻造，桟瓦葺で，１階は納戸と階段室に便所が附属し，２階は床の間付３畳間とする。建築年代が明確で，大規模屋敷の構成上欠かせない建築物として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005343"},{"id":"00004024","register_sub_id":"101","register_pk":"105014","name":"堀井家住宅米蔵","kana":"ほりいけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市穴師1-1","lat":34.542252,"lng":135.853165,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"29 － 0087","desc":"屋敷の西辺を区画するように建つ。土蔵造，平屋建であるが，桁行２１ｍと長く，内部は５室にわかれ，桟瓦葺屋根は切妻造の３連段違いとし，北妻側を入母屋造にする。外部に面した外壁は漆喰塗で腰を縦板張とする。田園景観の中で際だった存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004024"},{"id":"00004020","register_sub_id":"101","register_pk":"105010","name":"堀井家住宅主屋","kana":"ほりいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県桜井市穴師1-1","lat":34.54232974,"lng":135.85336561,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積223㎡","structure_material":"木造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"29 － 0083","desc":"東方の三輪山に正面を向けて建つ。木造２階建，切妻造，桟瓦葺，正面と背面に下屋を設ける。南側を土間，北側を居室部とした平面で，上質の材を丁寧に仕上げ，堅牢かつ緻密に組んでいるが，ガラス戸の多用など，伝統の中に近代的なつくりが組み込まれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004020"},{"id":"00004022","register_sub_id":"101","register_pk":"105012","name":"堀井家住宅長屋門","kana":"ほりいけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県桜井市穴師1-1","lat":34.542339,"lng":135.85347,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"29 － 0085","desc":"敷地東辺のほぼ中央にある。南北棟の桟瓦葺で，南を切妻造，北を入母屋造とし，中央部は門口，左右が部屋になる。中央部は欅材を用い，正面軒を出桁造とし，扉上部には繊細な筬欄間を入れる。穴師川の清流と一体となって屋敷正面の構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004022"},{"id":"00004021","register_sub_id":"101","register_pk":"105011","name":"堀井家住宅離れ","kana":"ほりいけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市穴師1-1","lat":34.54242117,"lng":135.85328575,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"29 － 0084","desc":"主屋の北妻側に廊下で接続している。木造平屋建，入母屋造，桟瓦葺で，８畳の座敷と６畳の控えの間からなる。座敷は床・棚と付書院を備え，天井の棹縁を猿頬面取とするなど，端正な数寄屋風のつくりになる。部材等から江戸末期頃と推定される離れ座敷の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004021"},{"id":"00004025","register_sub_id":"101","register_pk":"105015","name":"堀井家住宅塀","kana":"ほりいけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県桜井市穴師1-1","lat":34.54246366,"lng":135.85341283,"geo_status":"db","era":"昭和7頃","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、瓦葺、延長30m","structure_material":"木造","registered":"2004.03.02(平成16.03.02)","register_no":"29 － 0088","desc":"長屋門から北に向かって延びる矩折の塀と，離れと土蔵との間に設けられた塀。土台状の切石上に建つ真壁造で，上部を漆喰塗，腰を縦板張とし，桟瓦葺の小屋根を架ける。屋敷の東辺と北辺の構えを整えるとともに，連続性のある建造物群の景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004025"},{"id":"00011371","register_sub_id":"101","register_pk":"209208","name":"正木家住宅蔵","kana":"まさきけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市毘沙門町13-2","lat":34.676303,"lng":135.832282,"geo_status":"db","era":"江戸後期／明治前期増築、昭和前期・平成22頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0231","desc":"主屋背面側に建つ。土蔵造二階建、切妻造本瓦葺の蔵で、軒まで漆喰で塗込める。西面に扉口を開き、主屋に面する西には縁を通して北端物入には丸窓を設ける。南側一間は明治期の増築で、さらに診療所時代に改造されている。主屋とともに中庭を画す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011371"},{"id":"00011370","register_sub_id":"101","register_pk":"209207","name":"正木家住宅主屋","kana":"まさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市毘沙門町13-2","lat":34.676279,"lng":135.832078,"geo_status":"db","era":"江戸後期／明治後期・昭和前期・平成20改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積169㎡、高塀付","structure_material":"木造平屋一部2階建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0230","desc":"奈良町の一角に西面して建つ切妻造桟瓦葺平入で、南端に土間を通し、床上部は二列七室で、南列に四室、北列は落棟とし、三室を並べる。北西側には坪庭を設ける。土間は吹き抜けとして架構を見せ、竈も残るなど、往時の町家の姿を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011370"},{"id":"00008325","register_sub_id":"101","register_pk":"133967","name":"松浦家住宅旧米蔵","kana":"まつうらけじゅうたくきゅうこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県北葛城郡王寺町久度2-3648-1","lat":34.59874893,"lng":135.70421373,"geo_status":"db","era":"明治43年頃／平成20年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"29 － 0196","desc":"敷地東辺南寄りに位置する。桁行６．０ｍ梁間４．０ｍの土蔵造平屋建。南北棟の切妻造桟瓦葺とし、西面に下屋庇を付設し、蔵前とする。切石基礎をまわし、水切り上を漆喰仕上げ、下を竪板張とし、南面上部に唐破風庇付の換気口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008325"},{"id":"00008321","register_sub_id":"101","register_pk":"133963","name":"松浦家住宅主屋","kana":"まつうらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県北葛城郡王寺町久度2-3648-1","lat":34.59889241,"lng":135.70410645,"geo_status":"db","era":"明治43年頃／昭和21年・昭和30年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積179㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"29 － 0192","desc":"敷地中央に位置する桁行１８ｍ梁間１０ｍの木造つし２階建で、東西棟の入母屋造桟瓦葺とし、東寄りを落棟とし、越屋根を付ける。西半部に仏間や座敷など六室を設け、南・北に縁を付ける。座敷にはトコや棚、付書院を構え、欄間や襖を飾り、良質な座敷をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008321"},{"id":"00008324","register_sub_id":"101","register_pk":"133966","name":"松浦家住宅道具蔵","kana":"まつうらけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県北葛城郡王寺町久度2-3648-1","lat":34.5990131,"lng":135.70398978,"geo_status":"db","era":"明治43年頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"29 － 0195","desc":"離れの西端に南北棟で続く２階建土蔵。桁行４．９ｍ梁間３．９ｍ、切妻造本瓦葺。置屋根形式で、その垂木や母屋も含め塗り込める。腰高の竪板張で、上部を漆喰仕上げとする。１、２階とも一室、壁は中塗仕上げとする。離れと一連で屋敷背後に重厚な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008324"},{"id":"00008323","register_sub_id":"101","register_pk":"133965","name":"松浦家住宅離れ","kana":"まつうらけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県北葛城郡王寺町久度2-3648-1","lat":34.59900774,"lng":135.70411047,"geo_status":"db","era":"明治43年頃／昭和60年・平成13年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"29 － 0194","desc":"主屋の北に位置する東西棟の木造平屋建で、取り合いの廊下を介して主屋に繋がる。切妻造桟瓦葺で、南面に下屋庇を付設。外壁は大壁の漆喰仕上げで、北面は高く竪板を張る。内部は南面に縁を通し、蔵前や六畳二室などを配する。屋敷構えを構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008323"},{"id":"00008326","register_sub_id":"101","register_pk":"133968","name":"松浦家住宅門長屋","kana":"まつうらけじゅうたくもんながや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県北葛城郡王寺町久度2-3648-1","lat":34.59886694,"lng":135.70423384,"geo_status":"db","era":"明治43年頃／昭和32年・平成20年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"29 － 0197","desc":"旧米蔵北面から敷地東辺を北へ伸びる。木造平屋建、桁行１９ｍ梁間３．０ｍ、切妻造桟瓦葺で、南端に表門を構え、北寄りに井戸や洗い場を設ける。外壁は腰板張で真壁造の漆喰仕上げ、内部は中塗仕上げとする。旧米蔵から連続して重厚な表構えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008326"},{"id":"00011998","register_sub_id":"101","register_pk":"210939","name":"松本家住宅内蔵","kana":"まつもとけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308","lat":34.55252949,"lng":135.7528021,"geo_status":"db","era":"昭和前期／昭和57年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階一部木造平屋建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階一部木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-254","desc":"主屋の西北端に蔵前を介して接する。土蔵造二階建、本瓦葺で、桁行四・九メートル、梁間三・九メートル。石積基礎の上に外壁漆喰塗籠、北面のみ腰板張とする。置屋根形式とするが、垂木等も塗籠め、一階東面と二階東及び南面に漆喰塗の庇付窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011998"},{"id":"00012004","register_sub_id":"101","register_pk":"210945","name":"松本家住宅表門","kana":"まつもとけじゅうたくおもてもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308","lat":34.552551,"lng":135.752999,"geo_status":"db","era":"昭和前期／昭和57年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積21㎡、西方潜戸及び土塀付","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-260","desc":"主屋の北側に位置する。西寄りには門番部屋を設け、東西には土塀を延ばす。建物は桁行三間半、梁間一間半、入母屋造桟瓦葺で、扉口は引分板戸の内側に引分格子戸を嵌め、西側袖壁には潜戸を設ける。南面には塀を延ばして庭門を開く。豪壮な造りの門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012004"},{"id":"00012006","register_sub_id":"101","register_pk":"210947","name":"松本家住宅北屋敷乾蔵","kana":"まつもとけじゅうたくきたやしきいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺299","lat":34.552726,"lng":135.752691,"geo_status":"db","era":"昭和5年／平成10年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積45㎡、土塀付","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"29-262","desc":"主屋から道路を隔てた北側敷地の北東隅に建つ土蔵。桁行一一・八メートル、梁間三・八メートル、総二階の切妻造本瓦葺で、東面に桟瓦葺の下屋を付す。内部は一、二階とも一室で、切石積の基礎を高く積み、東面中央に扉口を開く。敷地北側の景観を作る土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012006"},{"id":"00012007","register_sub_id":"101","register_pk":"210948","name":"松本家住宅北屋敷米蔵及び納屋","kana":"まつもとけじゅうたくきたやしきこめぐらおよびなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺299","lat":34.552749,"lng":135.75283,"geo_status":"db","era":"昭和前期／平成4年・同23年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋一部2階建、瓦葺、建築面積143㎡、納屋付","structure_material":"土蔵造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"29-263","desc":"敷地北辺に建つ東西棟土蔵。桁行一九・三メートル、梁間五・〇メートル、切妻造桟瓦葺で、小屋は和小屋とし、南面に深い下屋を設けている。西から板敷の米蔵、土間、板敷の納屋を配し、東半のみ二階を設ける。北側敷地の機能を知ることができる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012007"},{"id":"00012008","register_sub_id":"101","register_pk":"210949","name":"松本家住宅北屋敷西納屋","kana":"まつもとけじゅうたくきたやしきにしなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺299","lat":34.552647,"lng":135.752736,"geo_status":"db","era":"昭和前期／平成7年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積15㎡、板塀付","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-264","desc":"北側敷地の南西方に建つ。桁行二間半、梁間一間半の切妻造桟瓦葺で、東面を吹き放し、三方を腰板張、上部漆喰塗とする。内部は荒壁仕上で、床は土間である。農作業などの倉庫や作業場として用いられていたと思われ、かつての作業のありようを伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012008"},{"id":"00012009","register_sub_id":"101","register_pk":"210950","name":"松本家住宅北屋敷門屋","kana":"まつもとけじゅうたくきたやしきもんや","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺299","lat":34.552568,"lng":135.752856,"geo_status":"db","era":"昭和前期／平成6年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積39㎡、板塀付","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-265","desc":"北側敷地の南面に建つ。西側に番小屋、東側に門及び塀を配し、番小屋北面には物入が附属する。東端部は敷地形状に合わせてやや屈曲しているが、街路側からは腰を高く竪板張、上部を漆喰塗とする一連の景観を見せる。表門などと合わせ、街路側の景観を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012009"},{"id":"00012003","register_sub_id":"101","register_pk":"210944","name":"松本家住宅下男部屋及び柴小屋","kana":"まつもとけじゅうたくげなんべやおよびしばごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308","lat":34.552442,"lng":135.753071,"geo_status":"db","era":"昭和前期／昭和59年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-259","desc":"主屋の東に建つ。桁行一〇・〇メートル、梁間三・〇メートル、切妻造桟瓦葺で、南の道具蔵との間に居住部分内外を結ぶ通路を張り出すほか、北端部には主屋との間に門を設ける。内部は北側二室を居室、その南を柴小屋とする。農家の生活の有様を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012003"},{"id":"00011997","register_sub_id":"101","register_pk":"210938","name":"松本家住宅主屋","kana":"まつもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308","lat":34.552425,"lng":135.752918,"geo_status":"db","era":"昭和前期／昭和54年・同55年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積243㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"29-253","desc":"大和盆地中心部の環濠集落に建つ。木造二階建、切妻造桟瓦葺で、桁行一〇間、梁間五間の規模。東半を土間、西を二列三室の床上部とし、北と南に縁を通す。南面中央には浴室等を突出させ、南端に四畳半を設ける。良材を多く用い、細部造作にも秀でる住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011997"},{"id":"00011999","register_sub_id":"101","register_pk":"210940","name":"松本家住宅辰巳蔵","kana":"まつもとけじゅうたくたつみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308他","lat":34.552275,"lng":135.75304,"geo_status":"db","era":"明治期／昭和63年改修","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積74㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"29-255","desc":"主屋の南東方に建ち、敷地の南側を画す。桁行九・七メートル、梁間五・九メートルの土蔵造二階建で、屋根は本瓦葺、庇は桟瓦葺とする。外壁は腰板張、上部漆喰塗とする。南面西寄りに二箇所、東面妻に一箇所、庇を設ける小ぶりな窓を開く。敷地景観を作る土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011999"},{"id":"00012000","register_sub_id":"101","register_pk":"210941","name":"松本家住宅道具蔵","kana":"まつもとけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308他","lat":34.552352,"lng":135.753066,"geo_status":"db","era":"昭和前期／昭和60年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造2階一部木造平屋建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階一部木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-256","desc":"主屋南東方に建つ、桁行八・二メートル、梁間三・九メートルの土蔵造二階建で、屋根は桟瓦葺。一階は三室に区切り、背面側に便所を突出させる。二階は南端と中央から北の二室に区切る。食器類など家財道具を収めていた蔵で、豪農の暮らしを今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012000"},{"id":"00012001","register_sub_id":"101","register_pk":"210942","name":"松本家住宅南屋敷南東納屋","kana":"まつもとけじゅうたくみなみやしきなんとうなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308他","lat":34.55232992,"lng":135.75311694,"geo_status":"db","era":"昭和前期／平成元年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積24㎡、門付","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-257","desc":"辰巳蔵東端部から道具蔵の東側に建つ。東側の外観は腰部を高く竪板張とし、上部漆喰塗で板塀に見えるが、敷地内側は丸太柱を立てて屋根を深くかけ、吹放ち土間敷の空間とし、物置としている。南側二間半は壁を造って部屋とする。敷地東側の景観を作る納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012001"},{"id":"00012002","register_sub_id":"101","register_pk":"210943","name":"松本家住宅南屋敷北東納屋","kana":"まつもとけじゅうたくみなみやしきほくとうなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308他","lat":34.552537,"lng":135.753186,"geo_status":"db","era":"昭和前期／平成2年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積8.1㎡、門付","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"29-258","desc":"表門東方土塀の東に伸びる納屋。西半は塀のみで両開門を設け、東半は南側に柱を立てて吹放ちの物置としている。桁行一一・七メートルの規模で、唐臼部屋とも呼ばれ、農作業のための空間であったことが窺われる。豪農の住宅の機能を今に伝える納屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012002"},{"id":"00012005","register_sub_id":"101","register_pk":"210946","name":"松本家住宅南屋敷南及び西面塀","kana":"まつもとけじゅうたくみなみやしきみなみおよびにしめんへい","category":"住宅","subcategory":"建築物","type_guess":"塀","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県北葛城郡広陵町大字古寺308","lat":34.552317,"lng":135.752793,"geo_status":"db","era":"昭和前期／昭和62年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、瓦葺、延長39m","structure_material":"土塀","registered":"2017.10.27(平成29.10.27)","register_no":"29-261","desc":"内蔵南西端部から南に延び、敷地南西隅から南面西寄りまでを画す土塀。西面は延長二七・一メートル、南面は延長一一・六メートルで、いずれも南西隅側を一段切り下げる。屋根は桟瓦葺で、南面は柱を見せる。豪農の住宅にふさわしい景観を作る塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012005"},{"id":"00010876","register_sub_id":"101","register_pk":"201711","name":"松山家住宅米蔵","kana":"まつやまけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市西新屋町43-2","lat":34.67636,"lng":135.829498,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積71㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"29 ‐ 0225","desc":"敷地最奥部に、南北棟で東面して建ち、桁行七・九メートル梁間五・九メートルで、前面に奥行の広い下屋を付ける。正面の足元はモルタル仕上げ、上部は漆喰塗で鉢巻を廻らせる。建築後間もなく二階床を撤去したとみられる。米問屋としての盛期を伝える土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010876"},{"id":"00010873","register_sub_id":"101","register_pk":"201708","name":"松山家住宅主屋北棟","kana":"まつやまけじゅうたくしゅおくきたとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市西新屋町43-2","lat":34.67641,"lng":135.829833,"geo_status":"db","era":"文政12","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造2階建、瓦葺、建築面積97㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"29 ‐ 0222","desc":"主屋南棟より後退して建つ、つし二階建、切妻造桟瓦葺の町家。正面に丸太格子をつけ、上部外壁は黒漆喰塗で左右に虫籠窓を穿ち、両端に袖壁を付ける。内部は通土間沿いに三室を並べる。年代が明らかで奈良町の近世町家の基準作ともなり、歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010873"},{"id":"00010872","register_sub_id":"101","register_pk":"201707","name":"松山家住宅主屋南棟","kana":"まつやまけじゅうたくしゅおくみなみとう","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市西新屋町44","lat":34.676339,"lng":135.829848,"geo_status":"db","era":"江戸後期／平成12改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"29 ‐ 0221","desc":"奈良町中心部で東面して建つ町家。木造平屋建、切妻造桟瓦葺、平入で正背面に下屋を付ける。正面に格子をたて、上部外壁は黒漆喰塗で南寄りに虫籠窓を設ける。建ちが低く、差鴨居で固めた軸部や床などの造作も旧状をとどめ、近世に遡る町家として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010872"},{"id":"00010875","register_sub_id":"101","register_pk":"201710","name":"松山家住宅麦蔵","kana":"まつやまけじゅうたくむぎぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市西新屋町43-2","lat":34.676406,"lng":135.829597,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積45㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"29 ‐ 0224","desc":"渡廊下西側に南面する、東西棟、桁行六・九メートル梁間四・九メートル、土蔵造平屋建で、正面に下屋を付ける。両側面と背面は竪板張、正面の足元はモルタル仕上げ、上部は漆喰塗で鉢巻を廻らせる。内壁には荷摺木を残す。奈良町の商家の屋敷景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010875"},{"id":"00010874","register_sub_id":"101","register_pk":"201709","name":"松山家住宅渡廊下","kana":"まつやまけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市西新屋町43-2","lat":34.676403,"lng":135.829697,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"29 ‐ 0223","desc":"主屋北棟の背面、中庭に面して手摺のある渡廊下を配し、廊下の南側には、舞良戸や下地窓を有する浴室、便所を並べる。廊下の垂木を受ける長さ六メートルの丸太桁は、柱で受けず軒から吊り、開放的な空間を創出する。奈良町町家の中庭の特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010874"},{"id":"00014074","register_sub_id":"101","register_pk":"508334","name":"南家住宅主屋","kana":"みなみけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県御所市大字池之内923-1","lat":34.44762778,"lng":135.746975,"geo_status":"db","era":"江戸後期／明治45年・昭和40年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）一部瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"29 - 0326","desc":"奈良盆地南端の旧池之内村庄屋で薬種商の大和棟の民家。敷地北寄りに北面する東西棟。南北に下屋を付し東に落棟を配す。内部は東に土間及びシモミセ、西に二列六室を配し、北面上手は縁を付したザシキとし古式を残す。奈良盆地の豪農屋敷の中核をなす主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014074"},{"id":"00014076","register_sub_id":"101","register_pk":"508336","name":"南家住宅道具蔵","kana":"みなみけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県御所市大字池之内923-1","lat":34.44744444,"lng":135.74716111,"geo_status":"db","era":"江戸末期／昭和45年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積76㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"29 - 0328","desc":"主屋南東に位置する南北棟土蔵。切妻造桟瓦葺、西面に下屋を付して戸口を設け、東面に二箇所の窓を開ける。内部一階は土間一室で北西隅に階段を設け、二階は一室の板敷とする。外壁は軒裏まで塗込め、漆喰塗仕上とする。敷地東辺の景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014076"},{"id":"00014075","register_sub_id":"101","register_pk":"508335","name":"南家住宅別座敷","kana":"みなみけじゅうたくべつざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県御所市大字池之内923-1","lat":34.44746389,"lng":135.74696389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"29 - 0327","desc":"主屋の南に位置する別棟座敷。平屋建切妻造桟瓦葺、南北を錣葺とする。東は北面に式台風の構えを持つ四畳。西に六畳及び八畳を並べて続き座敷とし、その南北に縁を付して庭を臨む。八畳は西に床、南に花頭窓の付書院とする。旧家の屋敷に残る本格的な別座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014075"},{"id":"00014078","register_sub_id":"101","register_pk":"508338","name":"南家住宅木塀","kana":"みなみけじゅうたくもくべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県御所市大字池之内923-1","lat":34.44771389,"lng":135.74693056,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、延長24m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"29 - 0330","desc":"門屋の西に長く続いて、敷地北辺を区画する塀。切石の布積基礎に半間毎に柱を立て、東西延長の中央部でやや北側に突出する。腕木で軒桁を支持し、屋根は桟瓦葺とする。外壁は真壁造で漆喰塗仕上とし、北面のみ腰を縦板張とする。敷地北面の景観をつくる木塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014078"},{"id":"00014077","register_sub_id":"101","register_pk":"508337","name":"南家住宅門屋及び庭門","kana":"みなみけじゅうたくもんやおよびにわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県御所市大字池之内923-1","lat":34.44769167,"lng":135.74703889,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"門屋 木造平屋建、瓦葺、建築面積35㎡、庭門 瓦葺、総延長3.1m","structure_material":"門屋 木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"29 - 0329","desc":"敷地北辺に位置する入母屋造桟瓦葺の東西棟長屋門。中央西寄り二間の門口とし、両脇に室を配して物置とする。南西隅から南へ塀を延ばし、中程に引違戸を入れて庭門とする。外壁は真壁造漆喰塗仕上で腰を竪板張とする。旧家の表構えをつくる風格ある長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014077"},{"id":"00005193","register_sub_id":"101","register_pk":"106183","name":"山崎家住宅主屋","kana":"やまさきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市奈良阪町2152他","lat":34.70496807,"lng":135.83400772,"geo_status":"db","era":"文久2／昭和14頃曳家","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"29 － 0093","desc":"市北部を南北に貫く京街道の西側の敷地に，東面して建つ元青果問屋。桁行６間半，梁間５間半の規模で，切妻造，平入，越屋根付の木造つし２階建で，１階に出格子窓，つし２階に虫籠窓，袖卯建を設ける。物資の集散地として栄えた奈良阪町の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005193"},{"id":"00002084","register_sub_id":"101","register_pk":"103074","name":"山田酒店（茶房長谷路）内蔵","kana":"やまださけてん（さぼうはせじ）うちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市初瀬857","lat":34.53123662,"lng":135.9061058,"geo_status":"db","era":"文化9／大正初期移築","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積22㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0042","desc":"敷地の北東，茶房座敷と接続して建つ土蔵。主屋と同時期の建造になり，大正期に現在の屋敷構えを整えた際に現在地に曳屋した。木造２階建，切妻，桟瓦葺き。外壁は漆喰を塗り込め，鉄格子入窓を開ける。江戸末から続く酒店の土蔵として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002084"},{"id":"00002082","register_sub_id":"101","register_pk":"103072","name":"山田酒店（茶房長谷路）茶房座敷","kana":"やまださけてん（さぼうはせじ）さぼうざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"奈良県","address":"奈良県桜井市初瀬857","lat":34.53133173,"lng":135.90621987,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0040","desc":"敷地の北東に位置する離れの座敷。数寄屋風の木造２階建，屋根は東側を入母屋，西側を切妻とし桟瓦を葺く。１，２階とも中庭に面して広い開口部をもつ。１階は，床の間，棚，書院を備えた和室と次の間の和室を並べ，調理場を併設し，中庭に面して縁をまわす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002082"},{"id":"00002083","register_sub_id":"101","register_pk":"103073","name":"山田酒店（茶房長谷路）茶室","kana":"やまださけてん（さぼうはせじ）ちゃしつ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県桜井市初瀬857","lat":34.5311748,"lng":135.90642348,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積8.7㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0041","desc":"敷地南側，主屋東面に接続して建つ３畳台目床付茶室。木造平屋，壁面を鼠漆喰仕上げとし，屋根は寄棟の桟瓦葺とする。中庭に面した壁面には障子をたて大きな開口をとる。主屋や茶房座敷と同様，庭に面した茶房として長谷寺参拝の人々に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002083"},{"id":"00002085","register_sub_id":"101","register_pk":"103075","name":"山田酒店（茶房長谷路）庭門","kana":"やまださけてん（さぼうはせじ）にわもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県桜井市初瀬857","lat":34.53119214,"lng":135.90648376,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平重門、瓦葺、間口1.5m、袖塀及び西塀附属","structure_material":"木造平重門","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0043","desc":"茶室のすぐ脇に位置する穴門形式の庭門で，茶房の出入口となっている。外塀からやや奥にひいて建ち，左右にくの字型の袖塀を建てる。袖塀は，腰を板張，その上を鼠漆喰仕上げとし，桟瓦を葺く。通りに面して銅板葺きの庇をかけるなど，特徴的な形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002085"},{"id":"00002086","register_sub_id":"101","register_pk":"103076","name":"山田酒店（茶房長谷路）塀","kana":"やまださけてん（さぼうはせじ）へい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"奈良県","address":"奈良県桜井市初瀬857","lat":34.53128396,"lng":135.90643912,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造、瓦葺、延長28m","structure_material":"木造","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0044","desc":"主屋に接続し，屋敷地の南側を区切る板塀。中ほどに庭門を開く。腰を縦板貼り，その上は鼠漆喰仕上げとし桟瓦を葺く。茶房座敷，茶室，庭門と同様，現所有者の祖父，山田新氏の設計になる。長谷寺の参詣路のまちなみを構成する要素として重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002086"},{"id":"00011372","register_sub_id":"101","register_pk":"209209","name":"吉岡家住宅主屋","kana":"よしおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市北京終町17-1","lat":34.672505,"lng":135.828401,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0232","desc":"奈良町南端部に位置する町家で、切妻造桟瓦葺、平入、二階建。南正面に格子戸や出格子を構え、二階に虫籠窓を設け、軒は出桁で受ける。東側に通り土間、西側に三室を一列に並べる。ガラス障子を多用するなど昭和前期の奈良町の近代住居の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011372"},{"id":"00011373","register_sub_id":"101","register_pk":"209210","name":"吉岡家住宅渡廊下","kana":"よしおかけじゅうたくわたりろうか","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市北京終町17-1他","lat":34.672583,"lng":135.828397,"geo_status":"db","era":"昭和10／平成24改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積8.6㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"29－0233","desc":"主屋後方東寄りに続く桁行四・九メートル、切妻造の木造平屋建。東側に物入れや便所を配し、中庭に面する西側は縁を通して漆喰塗の壁と板戸、ガラス窓、腰高ガラス障子、ガラス窓による整然とした意匠でまとめる。中庭を画す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011373"},{"id":"00010220","register_sub_id":"101","register_pk":"198053","name":"吉田家住宅主屋","kana":"よしだけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市芝新屋町1-2他","lat":34.67694149,"lng":135.83061079,"geo_status":"db","era":"昭和7／昭和中期・昭和47頃・平成24改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積105㎡","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"29 － 0209","desc":"街路に西面する平屋一部二階建で、切妻造桟瓦葺。正面は瓦葺の庇をつけて出格子をたて、建ちの低い二階は横に長く格子窓を穿つ。戦後の改造により正面南寄りの大戸口奥に内庭を設けた。床上は二列六室とし、八畳奥座敷は付書院を設けるなど丁寧な造作とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010220"},{"id":"00007798","register_sub_id":"101","register_pk":"108779","name":"廊坊家住宅主屋","kana":"ろうのぼうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字初瀬870","lat":34.53085276,"lng":135.90588033,"geo_status":"db","era":"江戸末期／平成16・平成20改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"29-0141","desc":"長谷寺参道に水路を挟み南面する。間口１１ｍの木造つし２階建で、背面に平屋建の居間を付設する。切妻造桟瓦葺、正面に下屋庇を付け、上部を黒漆喰の大壁とし、白漆喰の虫籠窓を開ける。下部は出格子を構え、格子戸をたてる。門前町の伝統的な佇まいを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007798"},{"id":"00014667","register_sub_id":"101","register_pk":"515209","name":"阿瀬家住宅主屋","kana":"あぜけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字中町535-1他","lat":34.034925,"lng":135.17579167,"geo_status":"db","era":"江戸末期／明治後期増築、昭和40年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0341","desc":"中町通りに西面する漁網製造を営んだ大型町家。切妻造平入本瓦葺のつし二階建。内部は北側を通り土間とする居室一列型の間取りに、南に続き間座敷を増築。一階は大戸と出格子を構え、二階は虫籠窓を開ける。湯浅の歴史的町並みを形成し、繁栄の変遷を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014667"},{"id":"00014669","register_sub_id":"101","register_pk":"515211","name":"阿瀬家住宅米蔵","kana":"あぜけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字中町535-1","lat":34.03491944,"lng":135.17596944,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0343","desc":"漁網製造を営んだ商家の敷地背面側に南北棟で建つ米蔵。北隣道具蔵と一体で大屋根を架ける。土蔵造二階建、切妻造平入本瓦葺、入口に裏白と格子の引戸を立て、内部は各階板敷、一階北東隅に内部ブリキ貼の小部屋を設ける。漁網製造で栄えた湯浅の繁栄を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014669"},{"id":"00014668","register_sub_id":"101","register_pk":"515210","name":"阿瀬家住宅道具蔵","kana":"あぜけじゅうたくどうぐぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡湯浅町大字湯浅字中町535-1","lat":34.03498333,"lng":135.17597778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0342","desc":"漁網製造を営んだ商家の敷地背面側に建つ道具蔵。土蔵造二階建南北棟、切妻造平入本瓦葺で、南に並ぶ米蔵と一続きで大屋根を架ける。入口に裏白と格子の引戸を立て、各階板敷で、装飾は控えめで実用的。敷地の北東角を形成し、落ち着いた街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014668"},{"id":"00004605","register_sub_id":"101","register_pk":"105595","name":"泉家住宅座敷","kana":"いずみけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"和歌山県","address":"和歌山県有田郡広川町大字広字中ノ町1227","lat":34.02566983,"lng":135.17184011,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"30 － 0071","desc":"当家８代目の平兵衛が客用座敷として建設した。平屋建，切妻造，下屋庇付，桟瓦葺で，内部は１０畳の主室，９畳の次の間，玄関等からなり，各室とも天井が高い。全体に上質の材を用い，床・棚等の構えから欄間等の造作まで，繊細で丁寧なつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004605"},{"id":"00010492","register_sub_id":"101","register_pk":"199440","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県御坊市御坊33他","lat":33.888617,"lng":135.15837,"geo_status":"db","era":"大正前期／昭和前期改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階一部平屋建、瓦葺、建築面積187㎡","structure_material":"木造2階一部平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0205","desc":"御坊寺内町の中心部、日高別院の北東方の東町通りに西面して建つ町家。正面一階床上部は出格子、二階は鼠漆喰壁に隅を木瓜状に縁取る窓を穿つ。平面は喰違いの六間取とする。屋根は本瓦葺で、正面の下屋に当地でオダレと呼ぶ幕板を付け、地方的特色を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010492"},{"id":"00012440","register_sub_id":"101","register_pk":"531764","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田市糸我町中番1097","lat":34.06655,"lng":135.1829,"geo_status":"db","era":"江戸末期／明治43年増築、平成28年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"30-231","desc":"有田川下流域の丘陵の南麓にあり、地場産業である蜜柑発祥の由緒をもつ畑に南面して建つ。つし二階建、切妻造本瓦葺で、土間下手部分を落棟とする。内部はダイドコロが土間側に張出す食違い四間取である。長大で重厚な外観が山村景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012440"},{"id":"00012441","register_sub_id":"101","register_pk":"531765","name":"伊藤家住宅土蔵","kana":"いとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田市糸我町中番1097","lat":34.06660556,"lng":135.18276667,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"30-232","desc":"主屋の西方、敷地の奥に東面して建つ家財蔵。土蔵造二階建、南北棟の切妻造本瓦葺。外壁は漆喰塗の腰板張で、鉢巻を廻す。内部は竪板張とする。道路から望見できる北妻面は窓庇の持送りを繰形にして漆喰で塗籠めるなど、重厚な意匠で整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012441"},{"id":"00012442","register_sub_id":"101","register_pk":"531766","name":"伊藤家住宅納屋","kana":"いとうけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県有田市糸我町中番1097","lat":34.06648056,"lng":135.183,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積66㎡、門及び脇塀付","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"30-233","desc":"主屋の東側に建つ。二階建の桟瓦葺で、正面となる南を切妻造、道路に面する北を入母屋造とする。南側には門と脇塀を付す。内部は南半を板床の納屋、北半を居室、西側の吹放ち下屋を作業空間とする。敷地の北東部を占め、後方の屋敷構えをかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012442"},{"id":"00010493","register_sub_id":"101","register_pk":"199441","name":"伊藤家住宅離れ","kana":"いとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県御坊市御坊33他","lat":33.888665,"lng":135.158712,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"30 － 0206","desc":"主屋東側に渡廊下を介して建つ。八畳座敷二室と四畳半の小室からなる。主座敷は書院付の床と違棚を備え、ツガなどの良材を用いて建てられている。庭側は開放的な形式とするが、背面の隣地側は軒などを塗込めて延焼防止対策が講じられた、良質な離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010493"},{"id":"00000080","register_sub_id":"101","register_pk":"101070","name":"井上家住宅","kana":"いのうえけじゅうたく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市北野620-1","lat":34.27351732,"lng":135.24756919,"geo_status":"db","era":"江戸時代末期／昭和16移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造平屋建、瓦葺、建築面積231㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"30 － 0001","desc":"元は和歌山市永穂にあった農家を移築したもの。１階は四間取形式で西側に土間を設けている。屋根は入母屋造本瓦葺で，正面に２間の玄関を設ける豪壮な建物である。和歌山市北部の庄屋宅を代表する住宅であり，外観の城郭風の壁等に技能の高さがうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000080"},{"id":"00014661","register_sub_id":"101","register_pk":"515203","name":"井上家住宅（旧岩田家住宅）主屋","kana":"いのうえけじゅうたく（きゅういわたけじゅうたく）おもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市中三谷字西馬場脇195他","lat":34.27798333,"lng":135.34143611,"geo_status":"db","era":"大正5年頃／昭和後期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、瓦葺、建築面積181㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0335","desc":"紀の川北岸の段丘に位置する農家。入母屋造平入桟瓦葺で南面する一部二階建。整形四間取の西側に座敷を突き出す。座敷は付書院床構えを西面、床脇を北面に分けて配す特徴的な構成。良材と落ち着いた意匠で整えた近代和風の農家建築で歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014661"},{"id":"00014662","register_sub_id":"101","register_pk":"515204","name":"井上家住宅（旧岩田家住宅）土蔵","kana":"いのうえけじゅうたく（きゅういわたけじゅうたく）どぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市中三谷字西馬場脇195他","lat":34.278025,"lng":135.34129167,"geo_status":"db","era":"江戸末期／大正前期増築、平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0336","desc":"敷地の北西隅に東面して建つ土蔵。土蔵造二階建、切妻造桟瓦葺の置屋根形式とする。東面に下屋を付し、戸口は鳥居枠を飾る。小屋組は棟木や母屋を妻面柱で支える特徴的な造り。外壁は漆喰仕上、敷地外面の腰を縦羽目板張とし、土塀と一連で敷地の外郭をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014662"},{"id":"00014664","register_sub_id":"101","register_pk":"515206","name":"井上家住宅（旧岩田家住宅）土塀","kana":"いのうえけじゅうたく（きゅういわたけじゅうたく）どべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市中三谷字西馬場脇195他","lat":34.27779167,"lng":135.34134722,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土塀、瓦葺、総延長59m","structure_material":"土塀","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0338","desc":"農村旧家の長屋門西から敷地南・西辺と土蔵を介して敷地北東隅まで続く桟瓦葺土塀。総延長五九メートルで石積基礎に築き、土蔵の南側と北辺中央に通用口を設ける。敷地外面は緑泥片岩の小石を隙間なく貼り付ける独特の仕上げで、歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014664"},{"id":"00014663","register_sub_id":"101","register_pk":"515205","name":"井上家住宅（旧岩田家住宅）長屋門","kana":"いのうえけじゅうたく（きゅういわたけじゅうたく）ながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"昭和後","pref":"和歌山県","address":"和歌山県紀の川市中三谷字西馬場脇195他","lat":34.27782222,"lng":135.34150278,"geo_status":"db","era":"昭和45年","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"30 - 0337","desc":"敷地南辺の通りに面して建つ長屋門。入母屋造桟瓦葺で、中央に板戸両開きの門扉、西脇に潜り戸を付し、東を土間の納屋、西は三室北縁側付で、西室は舟底天井とする。外壁は真壁造漆喰仕上に腰を竪板張とし、土塀や通り沿いの水路と共に屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014663"},{"id":"00014292","register_sub_id":"101","register_pk":"509682","name":"上田家住宅乾蔵","kana":"うえだけじゅうたくいぬいぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市上田字荒瀬36","lat":34.31627778,"lng":135.62986389,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0327","desc":"紀ノ川南岸の旧家の土蔵で青石の石垣上に建ち、敷地北西隅の外郭となる。土蔵造二階建、切妻造桟瓦葺置屋根形式、北と西面腰板張とする。東面に下屋を付し、木瓜形に塗り回した入口に裏白戸を建てる。各階一室で北側に窓を開ける。屋敷景観に重要な乾蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014292"},{"id":"00014290","register_sub_id":"101","register_pk":"509680","name":"上田家住宅主屋","kana":"うえだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県橋本市上田字荒瀬36","lat":34.31618889,"lng":135.63004722,"geo_status":"db","era":"昭和4年頃／同53年・平成5年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0325","desc":"紀ノ川南岸に所在する旧家の住宅。入母屋造平入桟瓦葺、四周下屋、正面に入母屋造の玄関を構える。玄関東脇を居室、その裏を元は土間とした。表座敷は床構えを西に向け、離れ座敷と一体の接客空間とする。伝統的な佇まいに間取りの近代化が進んだ和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014290"},{"id":"00014522","register_sub_id":"101","register_pk":"513936","name":"上田家住宅米蔵及び中蔵","kana":"うえだけじゅうたくこめぐらおよびなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市上田字荒瀬36","lat":34.31628889,"lng":135.63000278,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"30 - 0333","desc":"紀ノ川南岸にある旧家の土蔵。主屋背面の川側に建ち、隙間を空けた土蔵二棟の正面庇と二階壁を繋げて一体とする。切妻造桟瓦葺置屋根で、壁は中塗仕上で軒は塗込、側背面ひしぎ竹張。横架材は丸太で屋根野地は割竹。川側に窓を左右対称に構え意匠を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014522"},{"id":"00014291","register_sub_id":"101","register_pk":"509681","name":"上田家住宅離れ座敷","kana":"うえだけじゅうたくはなれざしき","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市上田字荒瀬36","lat":34.31619444,"lng":135.62986944,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"30 - 0326","desc":"紀ノ川南岸の旧家の座敷棟。主屋の西に渡り廊下で繋がる入母屋造桟瓦葺の南北棟で敷地西外郭となる。真壁造中塗仕上、高く腰板を張る。南に床付き座敷を配した八畳三間続きの座敷で、庭側に縁を回す。良材を吟味し、細部に凝りながら端正な意匠にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014291"},{"id":"00012788","register_sub_id":"101","register_pk":"367691","name":"上南家住宅コナシヤ","kana":"うえみなみけじゅうたくこなしや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県海草郡紀美野町谷667","lat":34.1669775,"lng":135.30803583,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 254","desc":"主屋とヒヤの間に建つ納屋。木造平屋建、東西棟の入母屋造桟瓦葺で東面を出入口とする。内部は東を土間として、西端一間に床を張る。軸組に檜の新材と栗の古材を併用し、栗は前身建物の転用材とみられる。貴志川流域山間部の農家の伝統的な構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012788"},{"id":"00012786","register_sub_id":"101","register_pk":"367689","name":"上南家住宅主屋","kana":"うえみなみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海草郡紀美野町谷667","lat":34.1669775,"lng":135.30803583,"geo_status":"db","era":"江戸中期/明治後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 252","desc":"貴志川上流の山中にある農家兼茶屋。主屋は東斜面中腹の敷地中央に東面して建つ。入母屋造桟瓦葺の平屋建で、南に土間、北に前後2列に室を配し、前列を続き間の座敷とする。押板形式の床や床差しの竿縁天井など座敷回りを中心に古式を留める希少な民家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012786"},{"id":"00012789","register_sub_id":"101","register_pk":"367692","name":"上南家住宅長屋門","kana":"うえみなみけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海草郡紀美野町谷667","lat":34.1669775,"lng":135.30803583,"geo_status":"db","era":"江戸後期／昭和20年代・昭和中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 255","desc":"敷地南隅に南面して建つ。東面切妻造、西面入母屋造桟瓦葺の平屋建で、東端に門口を設ける。西側の室は背面を出入口とし、正面に張出して屋根を葺下ろす。内部はもと土間で炊事場や牛小屋に利用した。貴志川流域山間部の農家の伝統的な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012789"},{"id":"00012787","register_sub_id":"101","register_pk":"367690","name":"上南家住宅ヒヤ","kana":"うえみなみけじゅうたくひや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県海草郡紀美野町谷667","lat":34.1669775,"lng":135.30803583,"geo_status":"db","era":"昭和32年頃","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"30 － 253","desc":"敷地北隅に建つ離座敷。木造平屋建、東西棟の入母屋造桟瓦葺、内部は続き間の座敷で東南二面に縁を廻す。檜の良材を多用した丁寧なつくりで、吹寄せ・黒塗の竿縁天井や付書院の組子細工に時代感覚を現す。主屋上手に対峙して建ち、屋敷構えを引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012787"},{"id":"00007525","register_sub_id":"101","register_pk":"108507","name":"宇藤家住宅主屋","kana":"うとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市布施屋524","lat":34.243294,"lng":135.264755,"geo_status":"db","era":"明治前期／大正前期増築・平成12改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積206㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0135","desc":"敷地中央に南面して建つ木造平屋建。東西棟の入母屋造で下屋庇をまわし、南面に入母屋造の角屋を突き出し、西に落棟で入母屋造錣葺の座敷部を付ける。正面は上部壁を黒漆喰仕上げとし、下部は腰板張で黄漆喰仕上げとする。変化に富む外観をもつ近代農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007525"},{"id":"00007526","register_sub_id":"101","register_pk":"108508","name":"宇藤家住宅長屋門","kana":"うとうけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市布施屋524","lat":34.243183,"lng":135.264877,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0136","desc":"敷地南辺に位置する。桁行２０ｍ梁間３．６ｍの木造平屋建。東西棟で西端を入母屋造とし、東は納屋に接続する。ほぼ中央の間口３．７ｍを門口とし、両開戸と潜りを設け、東に板敷の倉庫、西に居室等を配する。外壁は高く竪板を張り、上部を白漆喰仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007526"},{"id":"00007527","register_sub_id":"101","register_pk":"108509","name":"宇藤家住宅納屋","kana":"うとうけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県和歌山市布施屋524","lat":34.243294,"lng":135.264923,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0137","desc":"敷地東辺に位置し、長屋門と直角に接続する。南北棟の入母屋造瓦葺で、桁行２０ｍ梁間４．０ｍ。赤味のある結晶片岩の基礎に建ち、外壁は上部を白漆喰仕上げ、下部を竪板張とする。南から倉庫、風呂・便所、倉庫と続く。長屋門と一連で重厚な屋敷構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007527"},{"id":"00007528","register_sub_id":"101","register_pk":"108510","name":"宇藤家住宅門","kana":"うとうけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市布施屋524","lat":34.243156,"lng":135.264679,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"30 － 0138","desc":"主屋西側の庭園に面し、敷地西辺の築地塀の中央に開けられた築地門。間口１．９ｍの切妻造桟瓦葺。本柱の前後に４本の控柱を配し、男梁を架し、束を立て棟木を支持する。軒は一軒疎垂木。弁柄塗がわずかに残る。熊野古道から見る屋敷西辺の構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007528"},{"id":"00005985","register_sub_id":"101","register_pk":"106970","name":"梅本家住宅主屋","kana":"うめもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中1-2-18","lat":34.19329966,"lng":135.16997363,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、瓦葺、建築面積146㎡","structure_material":"木造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"30 － 0113","desc":"街路に東面して建つ。南北棟の入母屋造，桟瓦葺，２階建で，周囲に下屋を廻す。正面の下屋を一文字葺とする。正面１階は出格子を連ね，２階壁面は黒漆喰塗とし，額縁付の木格子窓を設ける。重厚で丁寧なつくりの外観は，伝統的な町並景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005985"},{"id":"00006176","register_sub_id":"101","register_pk":"107160","name":"梅本家住宅土蔵","kana":"うめもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中1-2-18","lat":34.19336737,"lng":135.16981886,"geo_status":"db","era":"大正2頃","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"30 － 0114","desc":"南北棟の切妻造，桟瓦葺，平入の土蔵造２階建で，東面と南面に下屋を設け，１階は東面に扉口，南面に窓，２階は東面・北面に窓を設ける。小屋は地棟に登梁を架けた形式で，漆喰塗の外壁は腰を縦板で覆う。丁寧なつくりで，主屋とほぼ同時期の建築と見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006176"},{"id":"00006177","register_sub_id":"101","register_pk":"107161","name":"梅本家住宅納屋及び車庫","kana":"うめもとけじゅうたくなやおよびしゃこ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県和歌山市和歌浦中1-2-18","lat":34.19332607,"lng":135.16989652,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"30 － 0115","desc":"主屋の西に連続して建つ。南北棟の切妻造，桟瓦葺で，外壁は黒漆喰塗である。平面は東を納屋及び物置，西を車庫とし，出入口の車庫部北面は，両開きの板扉を設け，上部に格子窓を付ける。形式は簡素であるが，生活の変化に伴い造られた建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006177"},{"id":"00013755","register_sub_id":"101","register_pk":"504977","name":"浦家住宅隠居屋","kana":"うらけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1310","lat":34.02631111,"lng":135.17233611,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 302","desc":"主屋の西に建つ。二階建入母屋造桟瓦葺。北に通した縁沿いに二室、主屋との接続部に浴室等を配する。二階も二室配する。二階の西面はガラス戸を建て広湾を望む。北の座敷は床板に欅の一枚板、天井に笹杢の杉を用いる等、吟味した材料を用いた質の高い隠居屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013755"},{"id":"00013754","register_sub_id":"101","register_pk":"504976","name":"浦家住宅主屋","kana":"うらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1310","lat":34.02623889,"lng":135.17246111,"geo_status":"db","era":"明治後期／大正前期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積232㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 301","desc":"旧広村の中心に位置し、通りに東面して建つ。つし二階建入母屋造本瓦葺。南寄りに玄関を開け右脇は出格子を建て二階両脇に袖壁を掲げる。内部は三列六室で北に落棟で座敷部が付く。台所は小屋裏まで吹抜の大空間で見応えがある。材料を吟味した近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013754"},{"id":"00013756","register_sub_id":"101","register_pk":"504978","name":"浦家住宅文庫蔵","kana":"うらけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1310","lat":34.02639722,"lng":135.17230833,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 303","desc":"隠居屋の北に接続する。土蔵造二階建、切妻造桟瓦葺妻入。桁行四間梁間三間で外部は鉢巻まで漆喰で塗込める。東に蔵前をとり、観音開きの土戸を建て、冠木形を上部に付ける。内部は一、二階とも一室で内壁を漆喰で仕上げた上質なつくり。中庭の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013756"},{"id":"00013757","register_sub_id":"101","register_pk":"504979","name":"浦家住宅前蔵・中蔵及び櫨蔵","kana":"うらけじゅうたくまえぐら・なかぐらおよびはぜぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1310","lat":34.02628611,"lng":135.17220278,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積117㎡","structure_material":"土蔵造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"30 － 304","desc":"Ｌ字形平面で北から前蔵、中蔵、櫨蔵とする。土蔵造二階建一部平屋建切妻造桟瓦葺。腰を海鼠壁とし軒先まで塗込める。戸前は三箇所開け庇を付す。内部は板敷で壁は板壁。前蔵・中蔵の小屋は垂木を用いず厚板で野地をつくる。屋敷地中央の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013757"},{"id":"00016594","register_sub_id":"101","register_pk":"574956","name":"榎家住宅主屋","kana":"えのきけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県海南市孟子字階田648","lat":34.19099278,"lng":135.29880778,"geo_status":"db","era":"江戸末期／明治24年増築、平成30年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0419","desc":"貴志川左岸の農村集落に位置する旧家の主屋。敷地中央に南面して建つ、平屋建入母屋造桟瓦葺で南東に増築の座敷を突出する。１５畳の座敷は西に床を構え、南・東に縁を廻らし、庭を望む開放的なつくり。障壁画や襖絵で華やかに飾るなど上質な座敷を持つ主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016594"},{"id":"00016597","register_sub_id":"101","register_pk":"574959","name":"榎家住宅土蔵","kana":"えのきけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市孟子字下出561-2","lat":34.19099278,"lng":135.29880778,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積98㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0422","desc":"南側敷地の西端に東面して建つ土蔵。２階建切妻造平入桟瓦葺で、正面に吹放ちの下屋を付す。外壁は漆喰塗で上部に鉢巻を廻らす。各階２室の板敷で南は商品蔵、北は家財蔵に用いた。小屋組は束立の和小屋とする。大規模な土蔵で、集落の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016597"},{"id":"00016598","register_sub_id":"101","register_pk":"574960","name":"榎家住宅納屋","kana":"えのきけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市孟子字階田647","lat":34.19099278,"lng":135.29880778,"geo_status":"db","era":"昭和前期／昭和30年代改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0423","desc":"通りに北面して建つ長屋門。平屋建切妻造平入桟瓦葺で東妻に下屋を付し、外壁は漆喰塗で腰は竪板張の押縁留め。中央東寄りの門口は冠木や門扉はなく、東は板敷の物置、西は土間の納屋とし、いずれも小屋組を現す。長屋門形式の外観が集落の歴史的な景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016598"},{"id":"00016595","register_sub_id":"101","register_pk":"574957","name":"榎家住宅文庫蔵","kana":"えのきけじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市孟子字階田648","lat":34.19099278,"lng":135.29880778,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0420","desc":"主屋の北東に接して建つ家財蔵。２階建切妻造、置屋根形式の本瓦葺で、東と西に戸口を開ける。外壁は漆喰塗で腰は竪板張。各階板敷の一室で、小屋組は曲がりの強い梁を用いた和小屋とし野地板を流板に張る。質実なつくりで、集落の歴史的景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016595"},{"id":"00016596","register_sub_id":"101","register_pk":"574958","name":"榎家住宅繭蔵","kana":"えのきけじゅうたくまゆぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県海南市孟子字下出553-2","lat":34.19099278,"lng":135.29880778,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積130㎡","structure_material":"土蔵造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0421","desc":"主屋北西の高台に南面して建つ繭蔵。平屋建切妻造平入桟瓦葺で正面に下屋を付す。外壁漆喰塗で腰は竪板目板張。内部３室の各正面に戸口を開け、繭保管用に床は籾殻上に筵敷、壁・天井はトタン張で密閉する。妻面の換気用丸窓が外観のアクセントになる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016596"}];
